ALTER TABLE viaggi 
ADD COLUMN IF NOT EXISTS descrizione TEXT,
ADD COLUMN IF NOT EXISTS itinerario JSONB,
ADD COLUMN IF NOT EXISTS galleria_foto TEXT[];

SELECT id, mese, destinazione, 
       descrizione IS NULL AS descrizione_vuota,
       itinerario IS NULL AS itinerario_vuoto,
       galleria_foto IS NULL AS galleria_vuota
FROM viaggi 
ORDER BY id;


ALTER TABLE viaggi 
ADD COLUMN IF NOT EXISTS descrizione TEXT,
ADD COLUMN IF NOT EXISTS itinerario JSONB,
ADD COLUMN IF NOT EXISTS galleria_foto TEXT[];


UPDATE viaggi SET posti_totali = posti_disponibili WHERE posti_totali = 0;


SELECT id, mese, destinazione, posti_disponibili, posti_totali,
       descrizione IS NULL AS descr_vuota,
       itinerario IS NULL AS itin_vuoto,
       galleria_foto IS NULL AS gall_vuota
FROM viaggi 
WHERE id BETWEEN 1 AND 12
ORDER BY id;


// ID 1: NORVEGIA 
UPDATE viaggi SET 
descrizione = 'Svalbard on the road… O meglio, on the snow! Un itinerario mozzafiato in motoslitta self-drive, accompagnati da guide qualificate, alla scoperta delle terre più settentrionali del nostro pianeta. Una spedizione in piena regola, da veri pionieri, verso gli angoli più remoti e selvaggi dell''arcipelago: da Longyearbyen, «capitale» da poco più di 2000 abitanti, guideremo sotto il sole di mezzanotte attraverso sperdute valli spazzate dal vento artico e mastodontici ghiacciai, e dormiremo a Pyramiden, antico avamposti sovietici dove l''orologio si è fermato.',
itinerario = '[
  {"titolo": "Day 1: Arrivo ad Oslo", "immagine": "/Oslo.jpg", "testo": "<b>Mattina/Pomeriggio:</b> partenza in volo per Oslo dalle principali città Italiane, arrivo all''aeroporto di Oslo<br><br><b>Sera:</b> cena e serata nella capitale norvegese."},
  {"titolo": "Day 2: Arrivo alle Svalbard", "immagine": "/Svalbard.jpg", "testo": "<b>Mattina:</b> a seconda dell''operativo voli, visita a piedi del centro di Oslo<br><br><b>Pomeriggio:</b> trasferimento verso l''aeroporto e volo per Longyearbyen. Arrivo alle Svalbard e sistemazione in hotel<br><br><b>Sera:</b> cena e serata nei locali di Longyearbyen, la capitale ai confini del mondo"},
  {"titolo": "Day 3: Longyearbyen", "immagine": "/Longyearbyen.jpg", "testo": "<b>Mattina/Pomeriggio:</b> giornata a disposizione per la visita di Longyearbyen e dei suoi dintorni, con varie attività disponibili: visita della città con i suoi musei e il birrificio più settentrionale del mondo, tour delle spettacolari grotte di ghiaccio realizzato con slitte trainate dagli husky, uscita in kayak tra gli iceberg, boat safari e tante altre!<br><br><b>Sera:</b> cena e serata nei locali di Longyearbyen, la capitale ai confini del mondo"},
  {"titolo": "Day 4: Pyramiden", "immagine": "/Pyramiden.jpg", "testo": "<b>Mattina:</b> tour in motoslitta nelle remote lande a nord di Pyramiden, lungo il letto ghiacciato del Mimirelva e lo sfondo dei Monti Tor e Odino. Arrivo a Cima Comunismo, con vista panoramica sulle valli innevate<br><br><b>Pomeriggio:</b> pomeriggio dedicato alla visita di Pyramiden, l''insediamento umano più settentrionale al mondo: villaggio sovietico abbandonato, su cui troneggia ancora oggi una statua di Lenin, è rimasto perfettamente conservato tra i ghiacci artici, e qui il tempo si è fermato agli anni del comunismo e della guerra fredda<br><br><b>Sera:</b> cena e serata in hotel a Pyramiden"},
  {"titolo": "Day 5: Rientro ad Oslo", "immagine": "/Svalbard2.jpg", "testo": "<b>Mattina:</b> passeggiata guidata per il centro di Longyearbyen, visita dello Svalbard Museum e la Galleri Svalbard, che ospita più di 40 opere di Kåre Tveter, uno dei più importanti pittori norvegesi del ''900<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto di Longyearbyen e volo per Oslo. Trasferimento e sistemazione in hotel<br><br><b>Sera:</b> cena e serata nel centro della capitale della Norvegia"}
]'::jsonb,
galleria_foto = ARRAY['/Oslo.jpg', '/Svalbard.jpg', '/Longyearbyen.jpg']
WHERE id = 1;

// ID 2: LAPPONIA SVEDESE 
UPDATE viaggi SET 
descrizione = 'Laghi ghiacciati, valli montuose sommerse dalla neve, foreste di conifere solcate da fiumi impetuosi e torrenti gelati: la Lapponia svedese, in inverno, si trasforma in una stupenda cartolina ammantata di bianco! Partiremo in treno dalla bella Stoccolma, affascinante capitale della Svezia, alla volta di Kiruna, nel cuore della Lapponia svedese, dove il paesaggio si tinge di un bianco accecante. Vivremo il nostro sogno lappone dormendo in cabins di legno sulle sponde di un lago ghiacciato, e remoti camp immersi nella foresta. Intorno a noi il silenzio, interrotto solo dal rumore dei nostri sci, delle ciaspole, dallo sbuffare delle renne e dall''abbaiare pieno d''affetto degli husky. Un paradiso invernale vissuto tra relax e adrenalina. Pronti, partenza e via!',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Stoccolma", "immagine": "/Stoccolma.jpg", "testo": "<b>Mattina:</b> Partenza dall''Italia con voli con scalo per Stoccolma<br><br><b>Pomeriggio:</b> Arrivo a Stoccolma in serata, transfer verso il centro e check-in in hotel<br><br><b>Sera:</b> Cena in centro e serata nei locali trendy di Sodermalm, quartiere degli artisti e della nightlife di Stoccolma"},
  {"titolo": "Day 2: Stoccolma e treno per Kiruna", "immagine": "/Kiruna.jpg", "testo": "<b>Mattina:</b> Visita del Gamla Stan, incantevole centro storico di Stoccolma, che occupa la piccola isola di Stadsholmen. Passeggiata tra i vicoli e le eleganti case pastello risalenti 1700 che si affacciano sullo Stortorget, la pittoresca piazza centrale del Gamla Stan<br><br><b>Pomeriggio:</b> Visita opzionale del Palazzo Reale di Stoccolma e della Cattedrale, rientro in hotel per il ritiro bagagli, spesa e partenza con treno notturno alla volta di Kiruna, nel cuore della Lapponia svedese<br><br><b>Sera:</b> Cena «al sacco» e libero sfogo alla fantasia per una serata conviviale in treno. Notte in cuccetta"},
  {"titolo": "Day 3-4: Benvenuti in Lapponia", "immagine": "/Lapponia.jpg", "testo": "<b>Day 3 mattina/pomeriggio:</b> Arrivo alla stazione di Kiruna in tarda mattinata. Ritiro delle auto a noleggio e visita della cittadina, punto di partenza per eccellenza per le escursioni nella Lapponia svedese, nota per le sue temperature polari durante i mesi invernali<br><br><b>Day 4 pomeriggio:</b> Pranzo a Kiruna e tempo a disposizione per esplorare la città e i suoi dintorni, tra paesaggi artici e scorci unici del nord estremo della Svezia. Check-in in camp, dotato di bungalow e cottage in legno riscaldati, tipici della tradizione lappone<br><br><b>Day 4 sera:</b> Uscita libera per l''avvistamento dell''Aurora Boreale, lontano dalle luci del centro, per vivere l''emozione di una ricerca autentica e selvaggia del fenomeno naturale più affascinante del cielo lappone. Cena e serata in camp"},
  {"titolo": "Day 5: Tra foreste lapponi e l''iconico Ice Hotel", "immagine": "/Ice.jpg", "testo": "<b>Mattina:</b> Possibilità di partecipare agli eccitanti tour in slitta trainata dagli husky: rappresentano il metodo tradizionale per l''esplorazione del deserto subartico e delle foreste lapponi, oppure non mancheranno escursioni con le ciaspole o a piedi<br><br><b>Pomeriggio:</b> Pranzo a Kiruna, trasferimento e visita dell''Ice Hotel: il primo e più famoso hotel di ghiaccio al mondo: tutto, dai bar alle sale comuni, è scolpito nel ghiaccio, e gli ambienti sono arricchiti da splendide sculture e opere d''arte, anch''esse, ovviamente, fatte di ghiaccio! Come se non bastasse, è presente anche una sala delle cerimonie in ghiaccio dove si celebrano feste e matrimoni<br><br><b>Sera:</b> Seconda uscita serale a caccia dell''Aurora Boreale e serata in camp a Kiruna"},
  {"titolo": "Day 6: Kiruna e rientro in Italia", "immagine": "/Kiruna2.jpg", "testo": "<b>Mattina:</b> Rientro a Kiruna e consegna delle auto a noleggio<br><br><b>Pomeriggio:</b> Volo con scalo a Stoccolma e rientro in Italia… alla prossima avventura!"}
]'::jsonb,
galleria_foto = ARRAY['/Stoccolma.jpg', '/Kiruna.jpg', '/Lapponia.jpg']
WHERE id = 2;

// ID 3: LONDRA 
UPDATE viaggi SET 
descrizione = 'Londra non è solo una città: è un''esperienza che mescola storia millenaria, cultura contemporanea e un''energia unica al mondo. Passeggiando tra le sue strade, puoi passare in pochi minuti da palazzi reali a mercati alternativi, da musei iconici a quartieri multiculturali pieni di vita. Dalla maestosità del Buckingham Palace alla vista spettacolare dal London Eye, Londra sa sorprendere a ogni angolo. È una destinazione perfetta per ogni tipo di viaggiatore: romantica, culturale, dinamica e sempre indimenticabile.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Londra", "immagine": "/Londra.jpg", "testo": "<b>Mattina:</b> Arrivo a Londra e trasferimento in hotel. Tempo libero per rilassarsi o per una prima passeggiata nei dintorni.<br><br><b>Pomeriggio:</b> Inizio soft alla scoperta della città con una passeggiata lungo il Tamigi. Ammira il Tower Bridge e la Tower of London dall''esterno.<br><br><b>Sera:</b> Cena in un pub tipico inglese e passeggiata serale per assaporare la prima atmosfera londinese."},
  {"titolo": "Day 2: Il cuore storico di Londra", "immagine": "/BigBen.jpg", "testo": "<b>Mattina:</b> Visita al Buckingham Palace (possibilità di assistere al cambio della guardia) e passeggiata a St James''s Park.<br><br><b>Pomeriggio:</b> Proseguimento verso il Big Ben e il Palace of Westminster. Visita all''Westminster Abbey.<br><br><b>Sera:</b> Cena nella zona di Covent Garden con artisti di strada e atmosfera vivace."},
  {"titolo": "Day 3: Cultura e musei", "immagine": "/Longyearbyen.jpg", "testo": "<b>Mattina:</b> Visita al British Museum, uno dei musei più importanti al mondo.<br><br><b>Pomeriggio:</b> Passeggiata a Trafalgar Square e visita alla National Gallery.<br><br><b>Sera:</b> Spettacolo teatrale nel West End"},
  {"titolo": "Day 4: Londra moderna e panorami", "immagine": "/Paul.jpg", "testo": "<b>Mattina:</b> Salita sul London Eye per una vista panoramica mozzafiato.<br><br><b>Pomeriggio:</b> Visita al Borough Market per un pranzo street food, poi passeggiata verso la St Paul''s Cathedral.<br><br><b>Sera:</b> Cena lungo il Tamigi con vista sulla città illuminata."},
  {"titolo": "Day 5: Shopping e partenza", "immagine": "/Oxford.jpg", "testo": "<b>Mattina:</b> Shopping tra Oxford Street e Regent Street.<br><br><b>Pomeriggio:</b> Tempo libero per ultimi acquisti o visita a Hyde Park per una pausa rilassante.<br><br><b>Sera:</b> Trasferimento in aeroporto e partenza."}
]'::jsonb,
galleria_foto = ARRAY['/Londra.jpg', '/BigBen.jpg', '/Oxford.jpg']
WHERE id = 3;

// ID 4: TUNISIA 
UPDATE viaggi SET 
descrizione = 'Le porte del mondo arabo a pochi km dalle coste italiane. Questa è la Tunisia, piccolo gioiello affacciato sul Mediterraneo, che esploreremo in classico stile on the road andando alla scoperta delle variegate sfumature del paese: dalle atmosfere oniriche di Sidi Bou Said alle carismatiche medine di Tunisi e Sousse, dalle meraviglie puniche e romane di Cartagine e El Jem alle verdi oasi dell''interno, che esploreremo con un on the road dedicato tra villaggi trogloditi, deserti di sale e antichi ksar costruiti in fango.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Tunisi", "immagine": "/Tunisi.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza dall''Italia con volo per Tunisi. Arrivo all''aeroporto di Tunisi, ritiro auto a noleggio e trasferimento in città. Check-in in hotel<br><br><b>Sera:</b> Cena e serata nei locali della città vecchia di Tunisi"},
  {"titolo": "Day 2: Tunisi - medina e museo del Bardo", "immagine": "/medina.jpg", "testo": "<b>Mattina:</b> Giornata dedicata a Tunisi, l''affascinante capitale della Tunisia. Visita della grande Moschea Jamaa ez-Zitouna, esplorazione della medina, tra gli stretti souq, gli hammam e le terrazze delle residenze storiche, per uno spaccato di autentica tradizione e cultura araba a pochi km dall''Italia<br><br><b>Pomeriggio:</b> Pranzo nella medina e visita del Museo nazionale del Bardo che custodisce le collezioni archeologiche più importanti del Magreb e gli inestimabili mosaici romani, tra i meglio conservati al mondo<br><br><b>Sera:</b> Cena e serata a Tunisi"},
  {"titolo": "Day 3: El Jem", "immagine": "/ELJEM.jpg", "testo": "<b>Mattina:</b> Spostamento verso sud da Tunisi con una lunga giornata di trasferimento verso i deserti del sud del paese, non lontani dal confine con la Libia. Lungo il tragitto, sosta per la visita del maestoso anfiteatro di El Jem, il terzo più grande mai costruito dai Romani dopo il Colosseo e Capua, forse le più spettacolari tra le tante rovine romane e cartaginesi della Tunisia<br><br><b>Pomeriggio:</b> Prosecuzione dell''on the road verso sud in direzione Matmata, principale villaggio di un''affascinante regione ai margini del Sahara, ricca di insediamenti storici puntellati di abitazioni scavate nella roccia, utilizzate negli anni ''70 come set cinematografico per l''iconica saga di Star Wars. Visita dei villaggi trogloditi e check-in nella guesthouse scavata nella roccia<br><br><b>Sera:</b> Cena e serata a Matmata"},
  {"titolo": "Day 4: Oasi di Tozeur e Nefta", "immagine": "/Nefta.jpg", "testo": "<b>Mattina:</b> Sveglia presto e trasferimento in pieno deserto tra Ksar Ghilane e Tozeur, la più famosa oasi tunisina al confine con l''Algeria. Durante il tragitto, si attraverserà lo chott el-Jerid, splendido deserto di sabbia, sale e rari specchi d''acqua, che creano grandi contrasti cromatici e affascinanti miraggi. Arrivo a Tozeur e pranzo tra le viuzze della caratteristica medina con edifici color ocra<br><br><b>Pomeriggio:</b> Visita dell''oasi di Tozeur in quad tra gli oltre 1.000 ettari di palmeto e le 200 sorgenti, fino ad arrivare sulla collina di Tozeur dove si può ammirare un panorama che abbraccia i palmeti, lo chott el-Jerid, ed infine le dune del Sahara, indimenticabili alla luce del tramonto, raggiungibili dalla vicina oasi di Nefta. Visita del set cinematografico Star Wars di Mos Espa, a circa 20km da Tozeur, costruito letteralmente in mezzo al deserto<br><br><b>Sera:</b> Cena e serata nell''oasi di Tozeur"},
  {"titolo": "Day 5: Cartagine e Sidi Bou Said", "immagine": "/Cartagine.jpg", "testo": "<b>Mattina:</b> Visita della medina patrimonio Unesco di Sousse, sovrastata dalla kasbah e dalle fortificazioni del ribat, e trasferimento verso Tunisi. Pranzo durante il percorso (possibile sosta a Hammamet per pranzo lungo spiaggia)<br><br><b>Pomeriggio:</b> Arrivo nei quartieri settentrionali di Tunisi e visita di Cartagine, antica capitale punica: visita della collina di Byrsa, città bassa, e quartieri nord-occidentali, dove le rovine dell''anfiteatro, delle ville romane, del Teatro Romano e delle Terme di Antonino si fondono con le nuove ville di lusso dei ricchi abitanti di Tunisi. Breve trasferimento a Sidi Bou Said, perla tunisina a picco sul mare. Check-in in hotel e tè al tramonto sulle caratteristiche case bianche con infissi e tetti blu<br><br><b>Sera:</b> Cena e serata a Sidi Bou Said"},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Tunisi2.jpg", "testo": "<b>Mattina/Pomeriggio:</b> A seconda dell''orario dei voli, free time a Sidi Bou Said e spostamento verso l''aeroporto di Tunisi per il volo di rientro per l''Italia… E alla prossima avventura!<br><br><b>Sera:</b> Arrivo in Italia"}
]'::jsonb,
galleria_foto = ARRAY['/Tunisi.jpg', '/Tunisi2.jpg', '/Cartagine.jpg']
WHERE id = 4;

// ID 5: MAROCCO 
UPDATE viaggi SET 
descrizione = 'Pochi luoghi come il Marocco, con il caos dei souq e i silenzi delle kasbe, l''infinita palette di colori e i profumi inebrianti, sono in grado di stuzzicare la fantasia dei viaggiatori. Nel nostro on the road, la realtà supererà la fantasia: ci addentreremo, accompagnati da sapienti guide locali, nelle affollate medine delle città imperiali di Marrakech e Fes, attraverseremo vallate desertiche, oasi verdissime e foreste di montagna, e passeremo una notte indimenticabile in un camp tra le dune del Sahara. Ciliegina sulla torta, una serata all''insegna del relax e del divertimento a Chefchaouen, la celebre «città blu».',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Marrakech", "immagine": "/Marrakech.jpg", "testo": "<b>Mattina:</b> Partenza dall''Italia e arrivo a Marrakech, trasferimento in riad nel centro della medina<br><br><b>Pomeriggio:</b> Prima esplorazione dei souq della medina di Marrakech, dei giardini della Koutoubia e della piazza Jemaa el Fna, patrimonio dell''umanità UNESCO, in un festante caos di cartomanti, giocolieri, incantatori di serpenti, venditori di lumache, cantastorie. Tè al tramonto in uno dei rooftop sovrastanti la piazza<br><br><b>Sera:</b> Cena a base di street food negli stand di piazza Jemaa el Fna"},
  {"titolo": "Day 2: Marrakech", "immagine": "/Marrakech2.jpg", "testo": "<b>Mattina:</b> Visita della «città rossa» di Marrakech con guida parlante italiano: visita dell''antico quartiere ebraico della Mellah, il Palazzo Bahia, capolavoro dell''architettura arabo-andalusa, e visita dei labirintici souq degli artigiani del ferro e del cuoio<br><br><b>Pomeriggio:</b> Pranzo in caratteristico ristorante rooftop con affaccio sul souq delle spezie nella medina, e visita dei giardini Majorelle<br><br><b>Sera:</b> Cena in ristorante tipico per gustare le specialità marocchine. Serata nei locali di Marrakech."},
  {"titolo": "Day 3: Ait Ben Haddou", "immagine": "/Haddou.jpg", "testo": "<b>Mattina:</b> Partenza per Ouarzazate. Rapida e tortuosa salita verso il passo Tichka, uno dei più alti della catena dell''Atlante (2260 m), immersi in un magnifico scenario lunare. Trasferimento a Telouet e pranzo a base di tajine gourmet<br><br><b>Pomeriggio:</b> Scenic drive lungo la spettacolare valle di Ounila, dove il verdissimo fondovalle crea un fantastico contrasto cromatico con il rosso delle montagne, visita al tramonto del sito UNESCO dello ksar di Ait Ben Haddou. Tramonto e trasferimento in riad<br><br><b>Sera:</b> Cena e pernottamento in riad"},
  {"titolo": "Day 4: Valle del Dades e Merzouga", "immagine": "/Merzouga.jpg", "testo": "<b>Mattina:</b> Partenza per la Valle delle Rose e il villaggio di Skoura, attraverso la strada delle Mille Kasbah, puntellata di oasi brulicanti di vita. Sosta con pranzo al sacco panoramico presso il famoso viewpoint della valle del Dadès<br><br><b>Pomeriggio:</b> Arrivo a Merzouga e tour nel deserto dell''Erg Chebbi, famoso per le sue dune di sabbia che si stagliano altissime al confine con l''Algeria<br><br><b>Sera:</b> Notte indimenticabile in tenda nomade nel mezzo delle dune, serata al ritmo della musica, canti e danze del folclore berbero sotto a milioni di stelle"},
  {"titolo": "Day 5: Valle del Ziz, Azrou e Ifrane", "immagine": "/Azrou.jpg", "testo": "<b>Mattina:</b> Sveglia presto per vedere il magnifico spettacolo dell''alba nel deserto, rientro a Merzouga e partenza per Fes attraverso il «serpentone verde» della Valle dello Ziz<br><br><b>Pomeriggio:</b> Immersi in un surreale scenario alpino, visita della foresta incantata di Azrou, dove le bertucce vivono in libertà tra i boschi di cedro. Attraversamento della cittadina universitaria di Ifrane, conosciuta come la Svizzera marocchina. Cena e arrivo in serata a Fes<br><br><b>Sera:</b> Sistemazione in riad a Fes"},
  {"titolo": "Day 6: Fes", "immagine": "/Fes.jpg", "testo": "<b>Mattina:</b> Visita guidata in italiano della capitale religiosa, intellettuale e artistica del Marocco, tra i tortuosi labirinti dei souq, antichi caravanserrai e scuole coraniche<br><br><b>Pomeriggio:</b> Visita all''affascinante quartiere dei tintori e alle famose concerie della medina, con possibilità di acquistare articoli in pura pelle a prezzi vantaggiosi. Free time e possibilità di relax in un hammam tipico (opzionale, non incluso)<br><br><b>Sera:</b> Cena in ristorante marocchino e pernottamento in riad"},
  {"titolo": "Day 7: Chefchaouen", "immagine": "/Chefchaouen.jpg", "testo": "<b>Mattina:</b> Prosecuzione verso nord, attraverso paesaggi di montagna simil-alpini, alla volta di Chefchaouen, la splendida città blu marocchina<br><br><b>Pomeriggio:</b> Arrivo a Chefchaouen, autentico gioiellino a lungo tenuto protetto dagli sguardi stranieri. Free time immersi negli stretti vicoli della medina, tra le tipiche case di un abbagliante colore azzurro, adornate di massicce porte chiodate<br><br><b>Sera:</b> Cena e pernottamento a Chefchaouen"},
  {"titolo": "Day 8: Rabat", "immagine": "/Rabat.jpg", "testo": "<b>Mattina:</b> Partenza per Rabat, la capitale amministrativa e centro politico del Marocco. Spostamento in hotel e check in<br><br><b>Pomeriggio:</b> Arrivo a Rabat, passeggiata nella medina e visita dei vicoli dipinti di azzurro della Kasbah degli Oudaya, terminando nella bellissima terrazza affacciata sull''Oceano Atlantico<br><br><b>Sera:</b> Cena e serata a Rabat"},
  {"titolo": "Day 9: Tanger", "immagine": "/Tanger.jpg", "testo": "<b>Mattina:</b> Partenza per Tanger, si prende un treno da Rabat e si arriva a destinazione. Spostamento in hotel e check in<br><br><b>Pomeriggio:</b> Dopo pranzo, giro alla medina e al porto di Tanger<br><br><b>Sera:</b> Cena e serata a Tanger"},
  {"titolo": "Day 10: Rientro in Italia", "immagine": "/Casablanca.jpg", "testo": "<b>Mattina/Pomeriggio:</b> A seconda dell''operativo voli, spostamento verso Marrakech o Casablanca per il volo di rientro. Trasferimento in aeroporto per il volo di rientro in Italia… e alla prossima avventura!<br><br><b>Sera:</b> Arrivo in Italia"}
]'::jsonb,
galleria_foto = ARRAY['/Tanger.jpg', '/Marrakech.jpg', '/Casablanca.jpg']
WHERE id = 5;

// ID 6: PERÙ 
UPDATE viaggi SET 
descrizione = 'Vi porteremo alla scoperta del Perù che avete sempre sognato, lungo un itinerario completo e progressivo che attraversa il Paese dalla costa del Pacifico fino al cuore delle Ande. Partendo da Lima, ci sposteremo verso i paesaggi aridi e sorprendenti della costa meridionale, dove incontreremo una delle riserve marine più ricche del Sud America e il deserto punteggiato da misteri millenari come le Linee di Nazca. Il viaggio prosegue poi verso l''altopiano andino, tra le atmosfere coloniali di Arequipa, l''immensità del Canyon del Colca, le acque sacre del Lago Titicaca e, infine, la regione di Cusco, culla dell''Impero Inca. Dulcis in fundo, raggiungeremo Machu Picchu, una delle meraviglie archeologiche più iconiche del pianeta, e saliremo fino a oltre 5.000 metri per ammirare i colori surreali del Vinicunca, la Montagna Arcobaleno.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Lima", "immagine": "/Lima.jpg", "testo": "<b>Mattina:</b> Partenza dall''Italia con volo internazionale verso Lima, capitale del Perù. Giornata interamente dedicata al viaggio. Arrivo in serata e trasferimento in hotel e prima notte per recuperare dopo il volo intercontinentale.<br><br>*A seconda degli operativi voli, l''arrivo potrebbe essere spostato alla mattina del day 2"},
  {"titolo": "Day 2: Lima-Paracas", "immagine": "/Paracas.jpg", "testo": "<b>Mattina:</b> Dopo la colazione, visita del centro storico di Lima, patrimonio UNESCO. Passeggiata nella Plaza de Armas, cuore politico e religioso della città, e osservazione degli edifici coloniali che testimoniano il periodo del Vicereame del Perù<br><br><b>Pomeriggio:</b> Trasferimento lungo la Panamericana Sud verso Paracas, attraversando i paesaggi desertici della costa pacifica peruviana<br><br><b>Sera:</b> Arrivo a Paracas, sistemazione in hotel e cena sul mare"},
  {"titolo": "Day 3: Paracas-Huacachina", "immagine": "/Huacachina.jpg", "testo": "<b>Mattina:</b> Escursione in barca alle Isole Ballestas, importante riserva naturale marina. Durante la navigazione è possibile osservare colonie di leoni marini, pinguini di Humboldt e numerose specie di uccelli marini che popolano le scogliere<br><br><b>Pomeriggio:</b> Trasferimento verso l''oasi di Huacachina, circondata da alte dune di sabbia. Attività nel deserto con dune buggy (EXTRA) e sandboarding, attraversando uno degli ambienti più suggestivi della costa peruviana<br><br><b>Sera:</b> Tramonto sulle dune, cena e pernottamento a Huacachina"},
  {"titolo": "Day 4: Huacachina-Nazca-Arequipa", "immagine": "/Arequipa.jpg", "testo": "<b>Mattina:</b> Partenza in direzione Nazca, attraversando una delle aree più aride del Paese<br><br><b>Pomeriggio:</b> Arrivo a Nazca e osservazione delle Linee di Nazca dai miradores panoramici lungo la Panamericana. Possibilità di effettuare un volo panoramico facoltativo (EXTRA) per ammirare dall''alto i celebri geoglifi<br><br><b>Sera:</b> Cena a Nazca e partenza con bus notturno verso Arequipa"},
  {"titolo": "Day 5: Arequipa", "immagine": "/Arequipa.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Arrivo ad Arequipa, conosciuta come la «Ciudad Blanca», e sistemazione in hotel. Tempo libero per riposo. Visita del centro storico: Plaza de Armas, Iglesia de la Compañía, Monastero di Santa Catalina, uno dei complessi religiosi più importanti del Sud America, e passeggiata nel centro coloniale. Spostamento nel quartiere di Yanahuara, da cui si gode una vista panoramica sui vulcani che circondano la città<br><br><b>Sera:</b> Cena e pernottamento ad Arequipa"},
  {"titolo": "Day 6: Arequipa-Canyon del Colca", "immagine": "/Colca.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza e spostamento verso il Canyon del Colca, attraversando l''altopiano andino e il Mirador de los Andes, che supera i 4.800 metri di altitudine. Lungo il percorso è frequente l''avvistamento di lama, alpaca e vigogne. Arrivo nell''area del canyon e visita dei villaggi tradizionali affacciati sulle profonde gole del Colca, tra terrazzamenti agricoli pre-incaici e paesaggi andini<br><br><b>Sera:</b> Arrivo a Cabanaconde, sistemazione e cena. Pernottamento nel canyon"},
  {"titolo": "Day 7: Colca-Puno", "immagine": "/Puno.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Sveglia presto e visita del Mirador Cruz del Condor alle prime luci dell''alba, con vista impareggiabile sul canyon illuminato e solcato dal volo dei condor. Arrivo a Cabanaconde, colazione nel pueblo e partenza con bus turistico per Puno<br><br><b>Sera:</b> Arrivo a Puno, sulle rive del Lago Titicaca, sistemazione in hotel e pernottamento"},
  {"titolo": "Day 8: Cusco", "immagine": "/Cusco.jpg", "testo": "<b>Mattina:</b> Arrivo a Cusco nelle prime ore del mattino e sistemazione in hotel. Tempo dedicato all''acclimatamento all''altitudine<br><br><b>Pomeriggio:</b> Visita di Cusco, tra resti archeologici inca e architettura coloniale, in un contesto urbano che testimonia la sovrapposizione di due grandi civiltà<br><br><b>Sera:</b> Cena e pernottamento a Cusco"},
  {"titolo": "Day 9: Machu Picchu", "immagine": "/MachuPicchu.jpg", "testo": "<b>Mattina:</b> Trasferimento al sito archeologico di Machu Picchu e visita guidata completa della cittadella inca, tra templi, terrazze agricole e quartieri cerimoniali immersi nella foresta montana<br><br><b>Pomeriggio:</b> Rientro ad Aguas Calientes e proseguimento in treno verso Cusco<br><br><b>Sera:</b> Arrivo a Cusco e pernottamento"},
  {"titolo": "Day 10: Cusco-Lima-Italia", "immagine": "/Lima.jpg", "testo": "<b>Mattina:</b> Trasferimento in aeroporto e volo interno da Cusco a Lima. Volo internazionale e arrivo in Italia il Day 11… E alla prossima avventura!"}
]'::jsonb,
galleria_foto = ARRAY['/Cusco.jpg', '/Lima.jpg', '/MachuPicchu.jpg']
WHERE id = 6;

//ID 7: THAILANDIA 
UPDATE viaggi SET 
descrizione = 'Il nostro grande viaggio inizia da una grande capitale: ci immergeremo nell''atmosfera unica di Bangkok, dove templi sacri e vivace vita notturna si fondono in un affascinante connubio tra tradizione e modernità. L''imponente architettura di Ayutthaya e i suggestivi mercati galleggianti saranno il perfetto antipasto prima di raggiungere il grande nord e la sua capitale, la tranquilla e splendida Chiang Mai, con il suo fascino autentico e le sue atmosfere rilassate. Concluderemo in bellezza con 5 giorni di completo relax sulle isole di Koh Phangan e Ko Tao, tra indimenticabili beach party, bagni nel mare verde smeraldo e uscite di snorkeling sulla variopinta barriera corallina.',
itinerario = '[
  {"titolo": "Day 1-2: Arrivo a Bangkok", "immagine": "/Bangkok.jpg", "testo": "<b>Mattina:</b> Partenza dalle principali città italiane e volo per Bangkok<br><br><b>Day 2 mattina/pomeriggio:</b> Arrivo nel pomeriggio a Bangkok e trasferimento in hotel per check-in<br><br><b>Sera:</b> Aperitivo e cena a Bangkok"},
  {"titolo": "Day 3: Bangkok", "immagine": "/Bangkok2.jpg", "testo": "<b>Mattina:</b> Giro in battello sul fiume Chao Praya, arteria di comunicazione fondamentale per la capitale. Visita del Wat Pho, tempio del Buddha dormiente, noto per la sua gigantesca statua d''oro raffigurante Buddha in posizione sdraiata. Visita del Wat Arun, il tempio dell''alba<br><br><b>Pomeriggio:</b> Pranzo street food e prosecuzione della visita di Bangkok. Ingresso al Wat Phra Kaew, il più sacro e importante tra i templi della capitale, e visita del Palazzo Reale<br><br><b>Sera:</b> Aperitivo al Lebua at State Tower, il più bel rooftop di Bangkok per godere di una vista spettacolare sulla città. Cena e serata a Sukhumvit"},
  {"titolo": "Day 4: Ayutthaya", "immagine": "/Ayatthaya.jpg", "testo": "<b>Mattina:</b> Colazione e partenza in treno per Ayutthaya. Visita in bici dei principali templi della città, tra cui il Wat Mahathat, tempio della grande reliquia, noto per la testa del Buddha e il Wat Phra Sri Sanphet, il più sacro tra i templi del complesso dell''antico palazzo reale di Ayutthaya<br><br><b>Pomeriggio:</b> Pranzo e prosecuzione della visita libera in bici dell''isola di Ayutthaya. Rientro a Bangkok nel tardo pomeriggio<br><br><b>Sera:</b> Cena e serata a Bangkok, possibile visita del famoso quartiere a luci rosse di Pat-Pong"},
  {"titolo": "Day 5: Mercati di Mae Khlong e Amphawa", "immagine": "/Amphawa.jpg", "testo": "<b>Mattina:</b> Partenza in treno verso Amphawa e visita alla famosa ferrovia di Mae Khlong, nota per il fotogenico mercato che si svolge proprio sui binari, che viene prontamente smantellato ad ogni passaggio del treno. Prosecuzione in treno e tuk-tuk per Amphawa<br><br><b>Pomeriggio:</b> Arrivo a Amphawa, sede di uno dei più famosi, ma allo stesso tempo autentici, mercati galleggianti della Thailandia. Pranzo a base di street food e possibilità di noleggiare una barca per spostarsi lungo i canali del mercato, e contrattare con i venditori. Rientro a Bangkok nel tardo pomeriggio<br><br><b>Sera:</b> Cena libera e serata nei locali della City of Angels"},
  {"titolo": "Day 6: Doi Tung e Chiang Rai", "immagine": "/ChiangRai.jpg", "testo": "<b>Mattina:</b> Partenza prestissimo per l''aeroporto. Volo interno per Chiang Rai, arrivo e incontro con il nostro driver. Trasferimento verso il confine con il Myanmar e visita di Doi Tung, stupefacente residenza estiva della madre del sovrano thailandese, costruita in stile thai-svizzero e circondata da meravigliosi giardini. Rientro a Chiang Rai<br><br><b>Pomeriggio:</b> Visita del Wat Rong Khun, il celebre «tempio bianco» di Chiang Rai, di recente costruzione e tra i più eccentrici (e fotografati) di tutta la Thailandia. Foto all''esterno del tempio e visita dei bizzarri, coloratissimi interni<br><br><b>Sera:</b> Cena nei mercati serali di Chiang Rai, serata nei bar"},
  {"titolo": "Day 7: Chiang Mai", "immagine": "/ChangMai.jpg", "testo": "<b>Mattina:</b> Possibilità di assistere alla questua mattutina dei monaci buddhisti a Chiang Dao, e partenza al mattino in direzione di Chiang Mai. Breve sosta per la visita del tempio Wat Ban Den e arrivo a Chiang Mai. Check-in in hotel e pranzo in città<br><br><b>Pomeriggio:</b> Visita dei templi di Chiang Mai e free time nei mercati della città vecchia<br><br><b>Sera:</b> Cena nei mercati serali di Chiang Mai, serata nei bar"},
  {"titolo": "Day 8-9-10: Koh Phangan", "immagine": "/KohPhangan.jpg", "testo": "<b>Day 8:</b> Sveglia presto e volo da Chiang Mai a Surat Thani (scalo a Bangkok). Transfer in shuttle bus + traghetto, arrivo nel tardo pomeriggio a Koh Phangan, sistemazione in hotel<br><br><b>Day 9-10:</b> Relax nelle spiagge di Koh Phangan ed esplorazione dell''isola, serate nei bar e party sulla spiaggia"},
  {"titolo": "Day 11-12: Koh Tao", "immagine": "/KohTao.jpg", "testo": "<b>Day 11:</b> Transfer in traghetto a Koh Tao, sistemazione e relax<br><br><b>Day 12:</b> Snorkeling trip a largo di Koh Tao, presso la barriera corallina più bella, viva e ricca di fauna di tutta la Thailandia"},
  {"titolo": "Day 13: Rientro in Italia", "immagine": "/Thailandia.jpg", "testo": "<b>Mattina:</b> Rientro con traghetto + shuttle a Surat Thani, volo per Bangkok. Compatibilmente con gli orari dei voli, ultima serata a Bangkok e volo per l''Italia. Arrivo in Italia il day 14… e alla prossima avventura!"}
]'::jsonb,
galleria_foto = ARRAY['/Bangkok.jpg', '/ChangMai.jpg', '/KohPhangan.jpg']
WHERE id = 7;

// ID 8: ALGERIA 
UPDATE viaggi SET 
descrizione = 'L''Algeria è un paese immenso. A nord, si affaccia sull''Europa con la costa mediterranea, a latitudini maggiori di quelle della Sicilia; a sud, si protende tra Mali e Niger, incuneandosi nel profondo dell''Africa nera. Nel mezzo, la vastità del deserto del Sahara domina la scena. Partendo dalla capitale Algeri e dalla sua bianca Casbah che si tuffa nel Mediterraneo, ci lanceremo, a bordo di 4×4 guidati da driver locali, in un on the road leggendario lungo la N1, la mitica Transahariana, da Ghardaïa a Tamanrasset. Qui, nel profondo sud, andremo alla scoperta dell''Assekrem, la «Fine del Mondo» dei touareg, tra gli incredibili scenari del massiccio dell''Hoggar: trascorreremo una notte in rifugio a 2600 metri, e ammireremo il tramonto e l''alba più belli di tutto il Sahara.',
itinerario = '[
  {"titolo": "Day 1: Arrivo ad Algeri", "immagine": "/algeri.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia, arrivo ad Algeri, capitale dell''Algeria, spostamento in centro e check-in in hotel<br><br><b>Sera:</b> Cena in ristorante tradizionale del centro di Algeri."},
  {"titolo": "Day 2: Algeri", "immagine": "/elhamma.jpg", "testo": "<b>Mattina:</b> Visita della città nuova di Algeri. L''esplorazione inizierà da… un ufficio postale! La sede delle Poste Centrali di Algeri è infatti uno degli edifici più belli della città, con un bell''esterno neo-moresco e meravigliosi interni decorati con stucchi e finissimi mosaici. Dopo la vista di Algeri dall''alto del Giardino dell''Orologio Fiorito, visita del MAMA, interessante museo di arte moderno ospitato in un elegante edificio neo-moresco. Pranzo rapido in centro<br><br><b>Pomeriggio:</b> Da piazza Port Said, su cui si affaccia il teatro nazionale, spostamento verso la zona est del centro di Algeri, per la visita del bel giardino botanico El Hamma, affacciato sul mar Mediterraneo. Spostamento e visita del colossale Memoriale dei Martiri dell''indipendenza<br><br><b>Sera:</b> Cena in ristorante tradizionale del centro di Algeri"},
  {"titolo": "Day 3: Casbah di Algeri", "immagine": "/martiri.jpg", "testo": "<b>Mattina:</b> Itinerario a piedi alla scoperta della Casbah di Algeri. Da piazza dei Martiri, immersione nei vicoli della parte bassa della Casbah, visita del palazzo Dar Aziza e, da fuori, della moschea Ketchaoua, risalente al XVII secolo. Vista della Casbah di Algeri dall''alto, prosecuzione dell''esplorazione dei tortuosi vicoli tra i bianchi palazzi decadenti con porte colorate e pranzo a base di street food<br><br><b>Pomeriggio:</b> Discesa verso la costa, ai margini della Casbah, con visita al Palais des Rais. Trasferimento in aeroporto a metà pomeriggio per il volo interno per Ghardaïa<br><br><b>Sera:</b> Arrivo a Ghardaïa, check-in in hotel e cena"},
  {"titolo": "Day 4: Ghardaïa e valle dello M''zab", "immagine": "/ghardaia.jpg", "testo": "<b>Mattina:</b> Visita di Ghardaïa, capitale della Pentapoli mozabita, i 5 villaggi fortificati del Wadi M''zab<br><br><b>Pomeriggio:</b> Visita degli altri villaggi della Pentapoli, in particolare El Atteuf, Bou Noura e la città santa Beni Isguen. Relax nelle fresche oasi ai piedi dei villaggi mozabiti<br><br><b>Sera:</b> Cena e serata a Ghardaïa"},
  {"titolo": "Day 5: El Menia", "immagine": "/menia.jpg", "testo": "<b>Mattina:</b> Partenza in 4×4 verso sud, addentrandoci nel profondo del Sahara lungo la N1, la leggendaria strada transahariana, in direzione dell''oasi di El Menia. Arrivo in tarda mattinata, check-in in hotel e pranzo<br><br><b>Pomeriggio:</b> Visita dell''imponente ksar (fortezza) berbero e della chiesa di San Giuseppe, nel cui cortile si trova la tomba di Charles de Foucauld<br><br><b>Sera:</b> Cena e serata a El Menia"},
  {"titolo": "Day 6: N1 - Transahariana on the road", "immagine": "/salah.jpg", "testo": "<b>Mattina:</b> Giornata dedicata al trasferimento in 4×4 lungo la N1 verso In Salah. Pranzo durante il tragitto<br><br><b>Pomeriggio:</b> Prosecuzione del trasferimento transahariano e arrivo a In Salah nel pomeriggio. Check-in in hotel e visita del villaggio. Free time per l''esplorazione di In Salah<br><br><b>Sera:</b> Cena e serata a In Salah"},
  {"titolo": "Day 7: Road to Tamanrasset e Hoggar", "immagine": "/tamanrasset.jpg", "testo": "<b>Mattina:</b> Partenza in 4×4 lungo la N1 verso Tamanrasset, la mitica città del Sahara algerino lungo le vie carovaniere<br><br><b>Pomeriggio:</b> Attraversati aridi deserti di sabbia e roccia e altopiani, si raggiunge la catena montuosa dell''Hoggar, che si erge fino ai 2918 metri del monte Tahat. Arrivo alla capitale dei touareg, Tamanrasset, e check-in in hotel<br><br><b>Sera:</b> Cena e serata a Tamanrasset"},
  {"titolo": "Day 8: Assekrem", "immagine": "/assekrem.jpg", "testo": "<b>Mattina:</b> Salita in 4×4 all''Assekrem, «Fine del Mondo» nella lingua dei touareg, stupendo altopiano incastonato tra le vette dell''Hoggar<br><br><b>Pomeriggio:</b> Arrivo al piccolo rifugio di montagna a circa 2600 metri di altitudine. Con un trekking di circa un''ora, salita sino all''eremo di padre Foucauld, del 1911, sito a 2725 metri<br><br><b>Sera:</b> Cena e sguardo al cielo per ammirare la meravigliosa notte stellata dal rifugio sull''Assekrem"},
  {"titolo": "Day 9: Hoggar e rientro a Tamanrasset", "immagine": "/hoggar.jpg", "testo": "<b>Mattina:</b> Alba indimenticabile sulle pareti del massiccio dell''Hoggar, e rientro in 4×4 verso Tamanrasset, passando per una pista differente da quella dell''andata<br><br><b>Pomeriggio:</b> Rientro verso Tamanrasset attraverso magnifici scenari desertici. Check-in in hotel e visita della capitale tuareg<br><br><b>Sera:</b> Cena e serata a Tamanrasset"},
  {"titolo": "Day 10: Tamekrest e Tamanrasset", "immagine": "/tuareg.jpg", "testo": "<b>Mattina:</b> Partenza in 4×4 lungo la pista desertica per la regione del Tamekrest. Visita dei villaggi touareg del deserto e relax con pic-nic alla cascata del Tamekrest<br><br><b>Pomeriggio:</b> Rientro a Tamanrasset e visita della città. Free time nello splendido Marché Africain<br><br><b>Sera:</b> Cena a Tamanrasset e a letto presto per il volo dell''indomani"},
  {"titolo": "Day 11: Rientro ad Algeri e Tipasa", "immagine": "/tipasa.jpg", "testo": "<b>Mattina:</b> Sveglia molto presto e volo da Tamanrasset ad Algeri. Arrivo ad Algeri alle prime luci del mattino, trasferimento in centro e check-in in hotel. Possibilità di organizzare un''escursione a Tipasa<br><br><b>Pomeriggio:</b> Visita delle splendide rovine romane di Tipasa, affacciate sul mar Mediterraneo, e relax nella spiaggia di Chenoua. Rientro ad Algeri in bus nel tardo pomeriggio<br><br><b>Sera:</b> Cena in ristorante tradizionale del centro di Algeri"},
  {"titolo": "Day 12: Rientro in Italia", "immagine": "/italia.jpg", "testo": "<b>Mattina:</b> Trasferimento in aeroporto per il volo di ritorno.<br><br><b>Pomeriggio:</b> Arrivo in Italia."}
]'::jsonb,
galleria_foto = ARRAY['/ghardaia.jpg', '/tamanrasset.jpg', '/hoggar.jpg']
WHERE id = 8;

// ID 9: OMAN 
UPDATE viaggi SET 
descrizione = 'Scopri il fascino senza tempo di Oman, una terra dove tradizione e modernità si fondono armoniosamente, regalando esperienze autentiche e paesaggi sorprendenti. Dalle infinite distese dorate del deserto alle acque turchesi dell''Oceano Indiano, l''Oman è una destinazione che incanta ad ogni passo. Esplora antichi forti, villaggi arroccati tra le montagne e mercati profumati di spezie, oppure lasciati avvolgere dal silenzio magico delle dune sotto un cielo stellato. La capitale Muscat ti accoglie con la sua eleganza discreta, tra moschee imponenti e lungomari suggestivi, mentre le oasi nascoste (wadi) offrono scenari naturali perfetti per momenti di puro relax e avventura. Lasciati conquistare dall''ospitalità omanita, dalla cucina ricca di sapori e da un''atmosfera autentica e raffinata che rende ogni viaggio unico.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Mascate", "immagine": "/Mascate.jpg", "testo": "<b>Pomeriggio:</b> Partenza dall''Italia con voli con scalo per Mascate<br><br><b>Sera:</b> Arrivo a Mascate, noleggio auto 4×4 e check in in hotel e pernottamento"},
  {"titolo": "Day 2: Mascate", "immagine": "/Mascate2.jpg", "testo": "<b>Mattina:</b> Visita della moschea del Sultano Qaboos, la terza più grande del mondo e uno dei più impressionanti esempi di architettura islamica moderna. Noleggio dell''attrezzatura necessaria per il camping<br><br><b>Pomeriggio:</b> Visita del souq Mutrah, uno dei più colorati della penisola arabica. Prosecuzione della visita nel quartiere della Corniche, affacciato sull''oceano Indiano<br><br><b>Sera:</b> Cena e serata nei locali di Mascate"},
  {"titolo": "Day 3: Bimmah Sinkhole e Wadi Shab", "immagine": "/Wadi.jpg", "testo": "<b>Mattina:</b> Partenza presto lungo la strada costiera a sud di Mascat, visita e bagno rinfrescante nelle acque turchesi del Bimmah Sinkhole. Prosecuzione dell''itinerario e arrivo a Wadi Shab<br><br><b>Pomeriggio:</b> Pranzo nei pressi di Wadi Shab, prosecuzione dell''itinerario e arrivo a Ras Al Hadd. Allestimento del wild camp in una spiaggia deserta<br><br><b>Sera:</b> Opzionale, visita notturna guidata della Turtle Reserve di Ras Al Jinz"},
  {"titolo": "Day 4: Sugar Dunes", "immagine": "/SugarDunes.jpg", "testo": "<b>Mattina:</b> Sveglia presto, e nuova visita alla Turtle Reserve illuminata dalla splendida luce dell''alba<br><br><b>Pomeriggio:</b> Arrivo nei pressi delle Sugar Dunes, scenic drive tra le immense dune bianche per l''off road più eccitante del viaggio! Preparazione del wild camp<br><br><b>Sera:</b> Cena in tenda e serata sotto le stelle sull''immensa spiaggia affacciata sull''Oceano Indiano"},
  {"titolo": "Day 5-6: Benvenuti in paradiso!", "immagine": "/Barr.jpg", "testo": "<b>Mattina:</b> Arrivo a Barr Al Hikman, partendo dalle Sugar Dunes, ci aspettano 3 ore di macchina nel deserto on the road!<br><br><b>Pomeriggio:</b> Check-in nel whales camp che ci ospiterà per le prossime due notti. Dormiremo in un campeggio circondati da mare cristallino e sabbia bianca senza il troppo turismo di massa!<br><br><b>Sera:</b> Cena e serata in tenda"},
  {"titolo": "Day 7: Wahiba Sands", "immagine": "/Wadi2.jpg", "testo": "<b>Mattina:</b> Mattinata a disposizione nei pressi delle Sugar Dunes, tra un bagno nell''oceano e una derapata sulle dune<br><br><b>Pomeriggio:</b> Prosecuzione dell''itinerario verso il deserto rosso di Wahiba Sands. Tè di benvenuto e tramonto da Mille e una notte dall''alto delle dune del Wahiba Sands<br><br><b>Sera:</b> Cena e serata sotto milioni di stelle nel deserto dell''Oman"},
  {"titolo": "Day 8: Wadi Bani Khalid, arrivo a Nizwa", "immagine": "/Nizwa.jpg", "testo": "<b>Mattina:</b> Sveglia presto e camminata nel deserto all''alba tra le dune che si tingono di rosa. Colazione e partenza per Wadi Bani Khalid, bagno nelle piscine naturali dell''oasi<br><br><b>Pomeriggio:</b> Prosecuzione per Nizwa, dopo una breve visita alla polverosa cittadina di Ibra. Arrivo nel pomeriggio a Nizwa e visita del souq serale<br><br><b>Sera:</b> Sistemazione in hotel, cena e serata a Nizwa"},
  {"titolo": "Day 9: Jebel Shams", "immagine": "/Jebel.jpg", "testo": "<b>Mattina:</b> Visita del pittoresco mercato del venerdì di Nizwa, dedicato al commercio del bestiame. Visita del forte di Nizwa, il monumento più visitato dell''Oman<br><br><b>Pomeriggio:</b> Prosecuzione verso Jebel Shams, la montagna più alta dell''Oman, lungo una strada che si snoda in cima allo spettacolare Wadi Gul, il «grand canyon d''oriente». Arrivo al villaggio di Al Khitaym e allestimento del camp<br><br><b>Sera:</b> Wild camping sull''orlo del Wadi Gul"},
  {"titolo": "Day 10: Jebel Shams", "immagine": "/Jebel2.jpg", "testo": "<b>Mattina:</b> Sveglia presto e trekking lungo la cosiddetta «Balcony Walk», sentiero in cengia che taglia la parete a strapiombo del Wadi Gul. Arrivo al villaggio abbandonato di Sab. Rientro alle macchine e partenza verso Balad Sayt<br><br><b>Pomeriggio:</b> Percorso lungo strade panoramiche di montagna e visita del pittoresco villaggio di Balad Sayt. Rientro verso Mascate<br><br><b>Sera:</b> Cena e ultima serata nei locali di Mascate"},
  {"titolo": "Day 11: Arrivo in Italia", "immagine": "/Oman.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Arrivo in Aeroporto<br><br><b>Sera:</b> Volo notturno e arrivo in Italia… e alla prossima avventura!"}
]'::jsonb,
galleria_foto = ARRAY['/Mascate.jpg', '/Barr.jpg', '/Nizwa.jpg']
WHERE id = 9;

// ID 10: MAROCCO (Ottobre,  identico al Marocco di Maggio) 
UPDATE viaggi SET 
descrizione = (SELECT descrizione FROM viaggi WHERE id = 5),
itinerario = (SELECT itinerario FROM viaggi WHERE id = 5),
galleria_foto = (SELECT galleria_foto FROM viaggi WHERE id = 5)
WHERE id = 10;

// ID 11: COREA DEL SUD 
UPDATE viaggi SET 
descrizione = 'Storia millenaria e meraviglie hi-tech, la spiritualità buddhista e la mondanità del K-Pop: la Corea del Sud è terra di contrasti, che saranno il leit motiv di questo grande viaggio nel nuovo hub culturale dell''estremo oriente. Lasciata Seoul, faremo un viaggio nel tempo alla scoperta delle radici secolari del paese: una notte nel tempio di Golgulsa, dove i monaci residenti ci guideranno in rituali di meditazione zen. Busan ci stupirà invece con il suo skyline dominato dai grattacieli affacciati sul mar del Giappone, e a Seoul vivremo la perfetta sintesi tra la storia e la modernità più sfrenata, con un «salto» alla DMZ, per scoprire i segreti e la storia del famigerato confine con la Corea del Nord.',
itinerario = '[
  {"titolo": "Day 1-2: Arrivo a Seoul", "immagine": "/Seoul.jpg", "testo": "<b>Day 1:</b> Partenza dall''Italia con volo con scalo per Seoul<br><br><b>Day 2 pomeriggio:</b> Arrivo a Seoul, l''immensa capitale, hub storico e culturale della Corea del Sud, e trasferimento in hotel<br><br><b>Day 2 sera:</b> Cena e prima serata in Corea nei bar di Myeongdong, uno dei cuori della nightlife della capitale, o nel quartiere trendy di Gangnam"},
  {"titolo": "Day 3-4-5: Alla scoperta di Seoul", "immagine": "/Seoul2.jpg", "testo": "<b>Day 3:</b> Alla scoperta della Seoul antica e moderna<br><br><b>Day 4:</b> Mercati e N tower di Seoul<br><br><b>Day 5:</b> Tour guidato per andare a toccare con mano la guerra tra le due Coree. Alla scoperta della Zona Demilitarizzata. Il pomeriggio treno per Gyeongju, l''antica capitale della Corea del Sud"},
  {"titolo": "Day 6: Gyeongju", "immagine": "/Gyeongju.jpg", "testo": "<b>Mattina:</b> Passeggiata a Gyeongju e pranzo e visita della cittadina<br><br><b>Pomeriggio:</b> Visita dei complessi di tombe reali a tumulo di Gyeongju, sito patrimonio UNESCO. Nelle vicinanze, visita del palazzo di Donggung, affacciato sul laghetto artificiale Wolji, risalente al periodo della dinastia Silla<br><br><b>Sera:</b> Cena e serata a Gyeongju"},
  {"titolo": "Day 7-8: Busan", "immagine": "/Busan.jpg", "testo": "<b>Day 7 mattina:</b> Treno verso Busan partendo da Gyeongju<br><br><b>Day 7 pomeriggio:</b> Visita del villaggio di Gamcheon, nato come quartiere popolare degli anni ''30, riconoscibile per le sue pittoresche case colorate abbarbicate su una collina<br><br><b>Day 8 mattina/pomeriggio:</b> Visita nel quartiere di Nampo e pranzo a base di street food nei pressi di Jagalchi, il mercato del pesce più grande della Corea. Passeggiata nella vicina BIFF. Nel pomeriggio, relax nelle spiagge e nei parchi costieri di Busan<br><br><b>Day 8 sera:</b> Treno direzione Seoul e cena nella capitale"},
  {"titolo": "Day 9: Rientro in Italia", "immagine": "/Seoul.jpg", "testo": "<b>Pomeriggio:</b> Rientro in Italia con volo con scalo... E alla prossima avventura!"}
]'::jsonb,
galleria_foto = ARRAY['/Seoul.jpg', '/Busan.jpg', '/Seoul2.jpg']
WHERE id = 11;

// ID 12: CAPO VERDE 
UPDATE viaggi SET 
descrizione = 'Scopri la magia di Capo Verde, un arcipelago incastonato nell''oceano Atlantico dove natura incontaminata, clima perfetto tutto l''anno e cultura vibrante si incontrano per creare un''esperienza indimenticabile. Spiagge dorate lambite da acque cristalline, paesaggi vulcanici spettacolari e tramonti che sembrano dipinti ti aspettano in un paradiso ancora autentico. Che tu voglia rilassarti al sole, esplorare sentieri mozzafiato o immergerti nei ritmi coinvolgenti della musica locale, Capo Verde ha qualcosa di unico da offrirti. Lasciati conquistare dall''accoglienza calorosa della sua gente, dai sapori intensi della cucina creola e da un''atmosfera rilassata che ti farà dimenticare lo stress quotidiano. Ogni isola è un mondo a sé: dall''energia vivace di Sal e Boa Vista, alle montagne verdi di Santo Antão, fino al fascino culturale di São Vicente.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Capo Verde", "immagine": "/SantaMaria.jpg", "testo": "<b>Mattina:</b> Partenza dall''Italia e arrivo sull''isola di Sal. Trasferimento in hotel e sistemazione<br><br><b>Pomeriggio:</b> Relax in spiaggia a Santa Maria, con le sue acque turchesi e sabbia finissima.<br><br><b>Sera:</b> Cena in hotel o in ristorante locale con cucina tipica capoverdiana."},
  {"titolo": "Day 2: Relax e mare", "immagine": "/Capo.jpg", "testo": "<b>Mattina:</b> Giornata dedicata al relax in spiaggia o attività balneari (snorkeling, kite surf).<br><br><b>Pomeriggio:</b> Passeggiata sul pontile di Santa Maria Pier per osservare i pescatori locali.<br><br><b>Sera:</b> Cena in ristorante sul mare con musica dal vivo."},
  {"titolo": "Day 3: Escursione nell''isola di Sal", "immagine": "/Sal.jpg", "testo": "<b>Mattina:</b> Tour dell''isola: visita alle saline di Pedra de Lume, dove è possibile galleggiare come nel Mar Morto.<br><br><b>Pomeriggio:</b> Sosta alla Buracona per vedere la «Blue Eye» e continuazione del tour tra paesaggi vulcanici.<br><br><b>Sera:</b> Rientro e cena in hotel."},
  {"titolo": "Day 4: Avventura e natura", "immagine": "/Sal2.jpg", "testo": "<b>Mattina:</b> Escursione in quad o jeep tra dune e spiagge selvagge.<br><br><b>Pomeriggio:</b> Relax presso la spiaggia di Ponta Preta, famosa per le sue onde<br><br><b>Sera:</b> Serata libera a Santa Maria con locali e musica."},
  {"titolo": "Day 5-6-7: Boa Vista", "immagine": "/BaoVista.jpg", "testo": "<b>Day 5:</b> Visita le spiagge dell''isola di Boa Vista.<br><br><b>Day 6:</b> Visita al Deserto de Viana e alle spiagge incontaminate.<br><br><b>Day 7:</b> Rientro a Sal e cena."},
  {"titolo": "Day 8-9-10: Trasferimento a Santo Antão", "immagine": "/SantoAntao.jpg", "testo": "<b>Day 8:</b> Volo interno o trasferimento via São Vicente e traghetto per Santo Antão.<br><br><b>Day 9:</b> Arrivo e sistemazione in struttura immersa nella natura. Prime passeggiate tra montagne e vallate.<br><br><b>Day 10:</b> Escursione nella valle di Paul Valley, tra piantagioni di canna da zucchero e villaggi tradizionali. Continuazione del trekking con viste spettacolari su montagne e oceano. Relax e cena in guesthouse."},
  {"titolo": "Day 11-12: Ultime escursioni e relax", "immagine": "/Mare.jpg", "testo": "<b>Day 11:</b> Trasferimento verso la costa e relax presso Ponta do Sol.<br><br><b>Day 12:</b> Passeggiata leggera o escursione facoltativa tra i sentieri panoramici. Tempo libero per relax e foto nei punti più suggestivi. Cena di arrivederci sull''isola"},
  {"titolo": "Day 13: Rientro e partenza", "immagine": "/Sal.jpg", "testo": "<b>Mattina:</b> Rientro verso São Vicente e trasferimento in aeroporto<br><br><b>Pomeriggio/Sera:</b> Volo di ritorno per l''Italia"}
]'::jsonb,
galleria_foto = ARRAY['/Sal.jpg', '/BoaVista.jpg', '/Sal2.jpg']
WHERE id = 12;


SELECT id, mese, destinazione, 
       LENGTH(descrizione) AS lunghezza_descrizione,
       jsonb_array_length(itinerario) AS giorni_itinerario,
       array_length(galleria_foto, 1) AS num_foto
FROM viaggi 
WHERE id BETWEEN 1 AND 12
ORDER BY id;

SELECT column_name, data_type 
FROM information_schema.columns 
WHERE table_name = 'viaggi' 
ORDER BY ordinal_position;


UPDATE viaggi SET rotta = '/viaggio/' || id WHERE id BETWEEN 1 AND 12;


SELECT id, mese, destinazione, rotta FROM viaggi WHERE id BETWEEN 1 AND 12 ORDER BY id;

ALTER TABLE viaggi 
ADD COLUMN IF NOT EXISTS foto_header TEXT;

UPDATE viaggi SET foto_header = '/Norvegia.jpg' WHERE id = 1;
UPDATE viaggi SET foto_header = '/Lapponia.jpg' WHERE id = 2;
UPDATE viaggi SET foto_header = '/Londra.jpg' WHERE id = 3;
UPDATE viaggi SET foto_header = '/Tunisia.jpg' WHERE id = 4;
UPDATE viaggi SET foto_header = '/Marocco.jpg' WHERE id = 5;
UPDATE viaggi SET foto_header = '/Peru.jpg' WHERE id = 6;
