-- ============ ID 25: TROMSO ============
UPDATE viaggi SET 
descrizione = 'Preparatevi a vivere una fiaba invernale oltre il Circolo Polare Artico. Questo viaggio di 6 giorni a Tromsø vi porterà nel cuore pulsante della Norvegia settentrionale, dove la natura detta le regole e regala spettacoli mozzafiato. Immaginate di sfrecciare su slitte trainate da husky felici attraverso foreste incantate, di navigare in silenzio tra fiordi maestosi per avvistare le balene e di ascoltare antiche leggende Sami attorno al fuoco di una tenda tradizionale. Ma la vera protagonista sarà lei, l''Aurora Boreale: la cercheremo lontano dall''inquinamento luminoso, sperando di vederla danzare nel cielo stellato con i suoi iconici nastri verdi e viola. Un''avventura che unisce l''adrenalina del Grande Nord al calore dell''ospitalità scandinava.',
itinerario = '[
  {"titolo": "Day 1: Partenza dall''italia", "immagine": "/Tromso.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dai principali aereoporti italiani verso Olso e poi da lì verso l''aereoporto di Tromso<br><br><b>Sera:</b> Arrivo in hotel check-in e relax"},
  {"titolo": "Day 2: L''Emozione degli Husky e la Caccia all''Aurora", "immagine": "/Tromso2.jpg", "testo": "<b>Mattina:</b> Trasferimento in un allevamento locale per un''esperienza indimenticabile: il dog sledding. Dopo un breve briefing, guiderete (o vi farete trasportare su) una slitta trainata da una muta di energici e affettuosi husky attraverso valli innevate e paesaggi fiabeschi.<br><br><b>Pomeriggio:</b> Rientro in città per scaldarsi con una bevanda calda. Salita mozzafiato con la funivia Fjellheisen fino alla cima del Monte Storsteinen (421 metri). Da qui godrete del panorama più bello su Tromsø, i fiordi e le montagne circostanti.<br><br><b>Sera:</b> L''avventura entra nel vivo. Partenza in minibus con guide esperte per la vera «Caccia all''Aurora Boreale». Ci sposteremo dove i cieli sono più limpidi, riscaldandoci con tute termiche, cioccolata calda e falò sulla neve mentre attendiamo la danza delle Luci del Nord."},
  {"titolo": "Day 3: La Cultura Sami e il Fascino delle Renne", "immagine": "/Tromso3.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Incontro con la cultura millenaria del popolo Sami. Visiteremo un accampamento tradizionale dove potrete nutrire le renne e fare un dolce e panoramico giro in slitta trainati da questi placidi animali, essenziali per la sopravvivenza nell''Artico.<br><br><b>Sera:</b> Serata libera. Consigliamo di provare una delle moderne saune galleggianti situate nel porto: l''esperienza nordica per eccellenza prevede sauna caldissima e un rapido, coraggioso tuffo nelle acque gelide del fiordo!"},
  {"titolo": "Day 4: Navigazione Silenziosa tra i Fiordi (e Whale Watching)", "immagine": "/Tromso4.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Imbarco su un moderno catamarano ibrido elettrico per una crociera ecosostenibile e silenziosa lungo i maestosi fiordi artici. Durante i mesi invernali (novembre-gennaio) avrete ottime possibilità di avvistare orche e megattere che si avvicinano alla costa per nutrirsi di aringhe.<br><br><b>Sera:</b> Cena libera. Potete optare per una seconda escursione fotografica per l''Aurora Boreale (le condizioni meteo variano, quindi avere due serate dedicate aumenta le probabilità di avvistamento) o godervi la vivace vita notturna della «Parigi del Nord»."},
  {"titolo": "Day 5: Adrenalina in Motoslitta e le Cupole di Ghiaccio", "immagine": "/Tromso5.jpg", "testo": "<b>Mattina:</b> Partenza verso le spettacolari Alpi di Lyngen o l''entroterra di Tamokdalen per un''elettrizzante escursione in motoslitta. Sfreccerete su laghi ghiacciati e sentieri forestali immacolati, guidati da istruttori esperti.<br><br><b>Pomeriggio:</b> Visita alle Tromsø Ice Domes, un incredibile hotel e bar scolpito interamente nella neve e nel ghiaccio ogni inverno. Ammirerete le sculture di ghiaccio illuminate e sorseggerete un drink analcolico in un bicchiere di vero ghiaccio.<br><br><b>Sera:</b> Rientro a Tromsø. Cena d''addio in uno dei ristoranti più rinomati della città, celebrando con un brindisi le emozioni vissute in questa magica settimana artica."},
  {"titolo": "Day 6: Arrivederci, Grande Nord!", "immagine": "/Tromso6.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo da Tromso verso Olso e poi da lì verso i principali aereoporti italiani"}
]'::jsonb,
foto_header = '/Tromso.jpg',
galleria_foto = ARRAY['/Tromso.jpg', '/Tromso3.jpg', '/Tromso2.jpg']
WHERE id = 25;

-- ============ ID 26: MESSICO ============
UPDATE viaggi SET 
descrizione = 'Ponte naturale che congiunge, fisicamente e culturalmente, America Latina e Nordamerica, il Messico è uno dei paesi più affascinanti, variegati e complessi al mondo. Seguiremo un itinerario di bellezza sconvolgente, dall''immensa capitale Città del Messico alle celebri coste puntellate di monumenti Maya dello Yucatán, viaggiando per più di 2000 chilometri tra antichi vulcani, altopiani, canyon, piscine naturali, cenotes e verdissime foreste. Vivremo un Messico di altri tempi, immergendoci nelle atmosfere colorate, nelle musiche e nella gastronomia di strada degli splendidi centri coloniali dell''Oaxaca e del Chiapas, per un''avventura on the road semplicemente indimenticabile!',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Città del Messico", "immagine": "/Messico.jpg", "testo": "<b>Mattina:</b> Partenza dai principali aeroporti Italiani<br><br><b>Pomeriggio:</b> Arrivo all''aeroporto di Città del Messico, ritiro auto a noleggio e trasferimento in hotel in zona Zócalo, la meravigliosa e immensa piazza centrale della città<br><br><b>Sera:</b> Cena e serata a Città del Messico"},
  {"titolo": "Day 2-3: Citta del Messico", "immagine": "/Messico2.jpg", "testo": "<b>Day 2:</b> Giornata dedicata alla visita della capitale. Visita del centro storico: Palacio Nacional, la cattedrale, che sorge accanto alle rovine del Templo Mayor, risalente all''antica capitale azteca Tenochtitlán, e prosecuzione fino a Torre Mayor per una vista su tutta la città. Spostamento a Polanco per pranzo e per il pomeriggio<br><br><b>Day 3:</b> Visita del Castello di Chapultepec, arrivo a Coyoacán per la visita del museo di Frida Kahlo e tramonto da Nostra Signora di Guadalupe. Rientro in centro per una cerveza dal Tio Pepe"},
  {"titolo": "Day 4-5-6: Chichen Itza, Ik Kil e Coba", "immagine": "/ChichenItza.jpg", "testo": "<b>Day 4-5:</b> Partenza per Chichen Itzá e visita del sito all''alba. Considerata una tra le sette meraviglie del mondo, è senza dubbio il sito Maya più noto dello Yucatán e di tutto il Messico. La visita all''alba consentirà di anticipare l''arrivo dei pullman di turisti dalla vicina riviera Maya. Bagno nel vicino Ik Kil, meraviglioso cenote fiocamente illuminato dalla luce che filtra dall''alto. Arrivo a Valladolid, piccolo e grazioso centro abitato in stile coloniale, visita e pranzo<br><br><b>Day 6 pomeriggio:</b> Prosecuzione per Coba e visita della splendida piramide Maya, una delle poche su cui è concesso salire. Ultimo tratto del viaggio odierno, arrivo in serata a Tulum, check-in in hotel, passeggiata e aperitivo sul mare<br><br><b>Day 6 sera:</b> Cena in riva al mare a Tulum"},
  {"titolo": "Day 7-8-9: Tulum", "immagine": "/Tulum.jpg", "testo": "<b>Day 7-8:</b> Intera giornata a disposizione: sarà possibile passare una giornata di totale relax a Tulum o in alternativa compiere escursioni tra i meravigliosi luoghi di interesse naturalistici e culturali dello Yucatán, quali il cenote Dos Ojos, Akumal, cenote Cristal, e molti altri<br><br><b>Day 9:</b> Partenza presto per Chiquilá, rilascio auto a noleggio e traghetto per Isla Holbox. Check-in in guesthouse, bagno e relax"},
  {"titolo": "Day 10-11: Isla Holbox", "immagine": "/Holbox.jpg", "testo": "<b>Day 10-11:</b> Relax a Isla Holbox, la meraviglia caraibica del Messico. Lontana anni luce dal trambusto della riviera Maya e di Playa del Carmen, è il posto migliore per staccare la spina dopo il lungo e eccitante on the road in terra messicana. La vita sull''isola scorre lenta, non ci sono auto e ci si muove a piedi o in bicicletta tra le tranquille vie sabbiose. Possibilità di organizzare escursioni in barca alla scoperta delle meraviglie sottomarine dell''isola e, nei mesi estivi, per avvistare gli squali balena. La sera, tranquille cene sul mare e una bevuta nei localini sulla spiaggia"},
  {"titolo": "Day 12: Cancun", "immagine": "/Cancun.jpg", "testo": "<b>Mattina:</b> Ultime ore di relax a Isla Holbox<br><br><b>Pomeriggio:</b> Traghetto per Chiquilá e trasferimento in bus verso Cancún, elettrizzante metropoli situata all''estremità della penisola dello Yucatán con splendido affaccio sul mar dei Caraibi, nonché uno degli epicentri della nightlife messicana. Check-in in hotel e aperitivo sul mare<br><br><b>Sera:</b> Tutti a far festa per l''ultima notte messicana"},
  {"titolo": "Day 13: Rientro in Italia", "immagine": "/Messico.jpg", "testo": "<b>Mattina:</b> Rientro in Italia con volo internazionale. Arrivo in Italia... E alla prossima avventura!"}
]'::jsonb,
foto_header = '/Messico.jpg',
galleria_foto = ARRAY['/Messico.jpg', '/Cancun.jpg', '/Tulum.jpg']
WHERE id = 26;

-- ============ ID 27: UGANDA ============
UPDATE viaggi SET 
descrizione = 'Uganda, la Perla d''Africa: così ebbe a definirla Winston Churchill nel 1907, durante un viaggio in Africa centrale. Oggi l''Uganda, dopo alcuni decenni travagliati, è pronta a svelarci di nuovo le sue meraviglie: un''avventura on the road ammantata di esotismo ci porterà a scoprire l''esplosione della natura più selvaggia dei grandi parchi ugandesi, dallo Ziwa Rhino Sanctuary alle Murchison Falls NP, dai grandi branchi di elefanti, bufali, zebre e i fantastici leoni arrampicatori del Queen Elizabeth NP agli scimpanze di Kyambura e alle Golden Monkey. Ma l''Uganda è soprattutto il paradiso dei gorilla: il trekking con le ultime famiglie di gorilla di montagna nella Foresta Impenetrabile di Bwindi, ai piedi dei Virunga, ci regalerà una delle emozioni più forti delle nostre vite.',
itinerario = '[
  {"titolo": "Day 1-2: Kampala e Ziwa Rhino Sanctuary", "immagine": "/Uganda.jpg", "testo": "<b>Day 1:</b> Partenza dalle principali città italiane e volo con scalo per Entebbe<br><br><b>Day 2:</b> Arrivo ad Entebbe, in relazione all''orario di arrivo possibile check in in hotel e possibile visita di Kampala. Trasferimento verso nord, sosta a metà strada a Ziwa Rhino sanctuary. Unica riserva in Uganda dove è possibile osservare rinoceronti in libertà. Trekking-safari guidato nella riserva. Notte al santuario fuori dal parco di Murchison falls"},
  {"titolo": "Day 3-4: Murchison Falls National Park", "immagine": "/Uganda2.jpg", "testo": "<b>Day 3:</b> Safari fotografico nel settore a nord del Nilo dove si concentrano i game drive e i primi animali selvatici. Questo parco nazionale ospita una varietà e una quantità di fauna altissima ed essendo «tagliato» a metà dal Nilo e avendo il Lago Albert come confine naturale, offre un paesaggio estremamente verdeggiante e collinare<br><br><b>Day 4 mattina:</b> Sveglia all''alba e safari fotografico nella parte a nord del Nilo. Nel parco troviamo all''incirca 76 specie di mammiferi: elefanti, bufali, giraffe, leoni, leopardi, antilopi, Uganda kobs e molti altri; inoltre troviamo circa 450 specie di uccelli, alcuni dei quali molto rari. Pranzo al sacco sulle sponde del Nilo<br><br><b>Day 4 pomeriggio:</b> Crociera sul Nilo Vittoria fino ad arrivare a circa 500 metri dal punto in cui le cascate Murchison si immettono nel fiume, potendole ammirare in tutta la loro potenza e maestosità"},
  {"titolo": "Day 4-5: Queen Elizabeth National Park", "immagine": "/Uganda3.jpg", "testo": "<b>Day 4:</b> Colazione e spostamento verso il Queen Elizabeth NP. Sono circa 95 le specie di mammiferi qui presenti tra cui: leoni, elefanti, leopardi, Uganda kobs (impala), iene maculate, bufali e diverse specie di primati. Nel settore sud del parco denominato «Ishasha» sono presenti i climbing lions che si arrampicano sugli alberi<br><br><b>Day 5:</b> Trekking con gli scimpanzé nella foresta di Kyambura che offre una varietà di vegetazione incredibile ed ospita una folta comunità di Scimpanzè. Avvistamento non garantito al 100%. Crociera sul Kazinga Channel, che unisce Edward Lake e George Lake, con possibilità di osservare ippopotami, bufali, elefanti che si abbeverano al fiume, antilopi e uccelli anche molto rari."},
  {"titolo": "Day 6-7-8: Leoni Arrampicatori di Ishasha", "immagine": "/Uganda4.jpg", "testo": "<b>Day 6:</b> Trasferimento a sud del parco attraversando la foresta di Maramagambo. Arrivo nel settore di Ishasha in tarda mattinata per ammirare, con un pò di fortuna, i lion climbing, leoni che si arrampicano sui fig trees, alberi che si diramano a pochi metri di altezza<br><br><b>Day 7:</b> Spostamento verso il quartier generale di Bwindi impenetrabile forest per un briefing con i ranger del parco. Due ranger specializzati e i trackers ci accompagneranno nella foresta impenetrabile alla ricerca di una delle famiglie di Gorilla di Montagna<br><br><b>Day 8:</b> Sveglia all''alba per il trasferimento al Mghainga National Park dove avrà luogo il trekking golden monkey della durata di 3/4 ore. Possibilità di vedere anche specie di uccelli come il Ruwenzori Turaco e i colobi"},
  {"titolo": "Day 9-10: La linea dell''Equatore", "immagine": "/Uganda5.jpg", "testo": "<b>Day 9:</b> Colazione e ripartenza verso Kampala con sosta sulla linea dell''Equatore<br><br><b>Day 10:</b> Arrivo ad Entebbe e relax, dipendentemente dal piano voli, transfer per l''aeroporto"},
  {"titolo": "Day 11: Rientro in Italia", "immagine": "/Uganda6.jpg", "testo": "<b>Mattina:</b> Giornata in volo, arrivo in Italia in serata… E alla prossima avventura!"}
]'::jsonb,
foto_header = '/Uganda.jpg',
galleria_foto = ARRAY['/Uganda.jpg', '/Uganda3.jpg', '/Uganda4.jpg']
WHERE id = 27;

-- ============ ID 28: REPUBBLICA DOMINICANA ============
UPDATE viaggi SET 
descrizione = 'Dimenticate la solita vacanza: questo viaggio di 11 giorni è un''immersione totale nei contrasti e nelle meraviglie della Repubblica Dominicana. Lontano dai cliché, vi porteremo a scoprire il vero cuore dei Caraibi. Inizieremo passeggiando tra i vicoli acciottolati e la storia secolare di Santo Domingo, la prima città del Nuovo Mondo. Ci sposteremo poi verso il nord lussureggiante, nella penisola di Samaná, dove foreste incontaminate si tuffano in un oceano dalle sfumature smeraldo. Infine, ci lasceremo cullare dalle acque cristalline del Mar dei Caraibi a Bayahibe, tra atolli disabitati, stelle marine e barriere coralline. Un itinerario perfetto per chi cerca il giusto equilibrio tra esplorazione culturale, avventura nella natura e relax su spiagge da cartolina.',
itinerario = '[
  {"titolo": "Day 1-2: Partenza dall''italia", "immagine": "/Santodomingo.jpg", "testo": "<b>Day 1:</b> Volo dai principali aereoporti italiani verso Santo Domingo<br><br><b>Day 2:</b> Arrivati a destinazione, check-in e relax nella piscina dell''hotel"},
  {"titolo": "Day 3: Alla scoperta della capitale", "immagine": "/Santodomingo2.jpg", "testo": "<b>Mattina:</b> Visita guidata della Zona Colonial (Patrimonio UNESCO). Scoprirete la prima Cattedrale delle Americhe, il Pantheon Nazionale e l''antica Fortezza Ozama.<br><br><b>Pomeriggio:</b> Tempo libero per fare acquisti nelle caratteristiche botteghe di ambra e larimar (la pietra azzurra locale), o per perdervi tra i colori esotici e i profumi del Mercado Modelo.<br><br><b>Sera:</b> Cena in un ristorante tipico del centro per assaggiare la Bandera Dominicana (il piatto nazionale), seguita da musica dal vivo e qualche passo di merengue."},
  {"titolo": "Day 4-5: Relax a Punta Cana", "immagine": "/PuntaCana.jpg", "testo": "<b>Day 4 mattina:</b> Spostamento in macchina verso Punta Cana<br><br><b>Day 4 pomeriggio / Day 5:</b> Relax nel mare cristallino dei Caraibi"},
  {"titolo": "Day 6: Il paradiso terreste - Escursione a Isla Saona", "immagine": "/IslaSaona.jpg", "testo": "<b>Mattina:</b> Partenza in catamarano o lancia rapida. Sosta imperdibile alle «Piscine Naturali», un immenso banco di sabbia in mare aperto con acqua alla vita, abitato da bellissime stelle marine giganti.<br><br><b>Pomeriggio:</b> Sbarco a Isla Saona, perla del Parco Nazionale Cotubanamá. Pranzo a buffet sotto le palme e tempo infinito per bagni da cartolina e relax all''ombra delle palme da cocco.<br><br><b>Sera:</b> Rientro a Punta Cana a ritmo di bachata. Serata libera per riposarsi o passeggiare nel piccolo centro del villaggio."},
  {"titolo": "Day 7-8-9: Direzione Bayahibe", "immagine": "/Bayahibe.jpg", "testo": "<b>Day 7:</b> Spostamento in macchina verso Bayahibe e relax in hotel<br><br><b>Day 8-9:</b> Arrivo nel pittoresco e tranquillo villaggio di pescatori di Bayahibe. Sistemazione in resort e primi tuffi rilassanti nelle acque calme di Playa Dominicus."},
  {"titolo": "Day 10: Relax Assoluto e Tramonto d''Addio", "immagine": "/Santodomingo.jpg", "testo": "<b>Day 10 mattina/pomeriggio:</b> Giornata libera a completa disposizione. Godetevi i comfort della struttura, fate una lunga passeggiata sul bagnasciuga o perdetevi nella lettura di un libro.<br><br><b>Day 10 sera:</b> Direzione Santo Domingo e notte lì"},
  {"titolo": "Day 11: Rientro in Italia", "immagine": "/Santodomingo2.jpg", "testo": "<b>Mattina/pomeriggio:</b> Trasferimento in aereoporto, alla prossima!"}
]'::jsonb,
foto_header = '/IslaSaona.jpg',
galleria_foto = ARRAY['/Santodomingo.jpg', '/Bayahibe.jpg', '/IslaSaona.jpg']
WHERE id = 28;

-- ============ ID 29: AUSTRALIA ============
UPDATE viaggi SET 
descrizione = 'L''Australia è una destinazione che sembra racchiudere più mondi in uno: città moderne e vibranti, deserti sconfinati, foreste pluviali millenarie e una delle barriere coralline più spettacolari del pianeta. Qui puoi passare in pochi giorni dall''energia cosmopolita di Sydney ai paesaggi sacri e senza tempo dell''Outback, fino alle acque cristalline della Grande Barriera Corallina. Un viaggio di 18 giorni in Australia è un''esperienza epica, pensata per chi vuole scoprire l''essenza del continente: icone urbane, natura selvaggia e incontri ravvicinati con la fauna locale. L''itinerario alterna città iconiche come Melbourne e Sydney, meraviglie naturali come Uluru e la costa tropicale del Queensland, per un viaggio completo e indimenticabile.',
itinerario = '[
  {"titolo": "Day 1-2: Arrivo a Sydney", "immagine": "/Sydney.jpg", "testo": "<b>Day 1:</b> Partenza dai principali aereoporti italiani<br><br><b>Day 2:</b> Arrivo a Sydney e trasferimento in hotel"},
  {"titolo": "Day 3-4-5: In giro per la fantastica Sydney", "immagine": "/Sydney2.jpg", "testo": "<b>Day 3:</b> Visita al Sydney Harbour Bridge e tutte le sfaccettature della città<br><br><b>Day 4:</b> Relax a Bondi Beach<br><br><b>Day 5:</b> Escursione alle Blue Mountains e rientro a Sydney"},
  {"titolo": "Day 6-7-8: Verso Melbourne e alla scoperta del Great Ocean Road", "immagine": "/Melbourne.jpg", "testo": "<b>Day 6:</b> Volo per Melbourne. Street art e laneways<br><br><b>Day 7:</b> Partenza per la Great Ocean Road, visita ai Dodici Apostoli e rientro a Melbourne<br><br><b>Day 8:</b> Cultura e relax per la città di Melbourne."},
  {"titolo": "Day 9-10-11: Verso Uluru", "immagine": "/Uluru.jpg", "testo": "<b>Day 9:</b> Trasferimento a Uluru<br><br><b>Day 10-11:</b> Passeggiata intorno al monolite e due giorni di relax nella fantastica Uluru."},
  {"titolo": "Day 12-13-14: Queensland", "immagine": "/Queensland.jpg", "testo": "<b>Day 12:</b> Volo per Cairns e relax sul lungomare e cena tropicale<br><br><b>Day 13-14:</b> Escursione alla Grande Barriera Corallina, snorkeling e rientro a Cairns"},
  {"titolo": "Day 15-16-17: Gold Coast", "immagine": "/GoldCoast.jpg", "testo": "<b>Day 15-16:</b> Volo per Brisbane ed escursione alla Gold Coast, relax in spiaggia con tanto di surf<br><br><b>Day 17:</b> Musei e cultura, shopping"},
  {"titolo": "Day 18: Rientro in Italia", "immagine": "/Sydney.jpg", "testo": "<b>Mattina:</b> Volo per Sydney<br><br><b>Pomeriggio:</b> Volo per l''Italia"}
]'::jsonb,
foto_header = '/Sydney.jpg',
galleria_foto = ARRAY['/Sydney.jpg', '/GoldCoast.jpg', '/Queensland.jpg']
WHERE id = 29;

-- ============ ID 30: CAMBOGIA ============
UPDATE viaggi SET 
descrizione = 'La Cambogia è una destinazione che incanta con il suo mix di storia millenaria, natura rigogliosa e cultura vibrante. Dai maestosi templi dell''antico Impero Khmer alle spiagge tropicali ancora poco affollate, questo paese del Sud-Est asiatico offre un viaggio autentico e sorprendente. Il cuore spirituale è senza dubbio Angkor Wat, simbolo nazionale e uno dei siti archeologici più straordinari al mondo, ma la Cambogia è anche molto di più: mercati vivaci, villaggi galleggianti, giungle misteriose e una popolazione accogliente che rende ogni esperienza ancora più speciale.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Phnom Penh", "immagine": "/PhnomPenh.jpg", "testo": "<b>Mattina:</b> Arrivo a Phnom Penh e trasferimento in hotel<br><br><b>Pomeriggio:</b> Visita al Palazzo Reale di Phnom Penh e alla Pagoda d''Argento<br><br><b>Sera:</b> Passeggiata lungo il fiume Mekong e cena tipica"},
  {"titolo": "Day 2: Storia e memoria", "immagine": "/Cambogia.jpg", "testo": "<b>Mattina:</b> Visita al Museo del Genocidio Tuol Sleng<br><br><b>Pomeriggio:</b> Escursione ai Killing Fields di Choeung Ek<br><br><b>Sera:</b> Rientro e cena rilassante"},
  {"titolo": "Day 3: Verso Siem Reap", "immagine": "/SiemReap.jpg", "testo": "<b>Mattina:</b> Trasferimento a Siem Reap (volo o bus)<br><br><b>Pomeriggio:</b> Esplorazione del centro e dei mercati locali<br><br><b>Sera:</b> Spettacolo di danza Apsara"},
  {"titolo": "Day 4: Angkor Wat", "immagine": "/AngkorWat.jpg", "testo": "<b>Mattina:</b> Alba a Angkor Wat<br><br><b>Pomeriggio:</b> Visita ad Angkor Thom e al tempio Bayon<br><br><b>Sera:</b> Cena nel centro di Siem Reap"},
  {"titolo": "Day 5: Templi nella giungla", "immagine": "/Cambogia2.jpg", "testo": "<b>Mattina:</b> Visita a Ta Prohm<br><br><b>Pomeriggio:</b> Altri templi minori e relax<br><br><b>Sera:</b> Pub Street e vita notturna"},
  {"titolo": "Day 6: Villaggi galleggianti", "immagine": "/Cambogia.jpg", "testo": "<b>Mattina:</b> Escursione al Lago Tonle Sap<br><br><b>Pomeriggio:</b> Visita ai villaggi galleggianti<br><br><b>Sera:</b> Cena tranquilla"},
  {"titolo": "Day 7: Verso il mare", "immagine": "/Sihanoukville.jpg", "testo": "<b>Mattina:</b> Trasferimento a Sihanoukville<br><br><b>Pomeriggio:</b> Relax in spiaggia<br><br><b>Sera:</b> Cena vista mare"},
  {"titolo": "Day 8-9-10: Isola tropicale", "immagine": "/KohRong.jpg", "testo": "<b>Day 8:</b> Traghetto per Koh Rong<br><br><b>Day 9-10:</b> Bagni e relax"},
  {"titolo": "Day 11: Rientro a Phnom Penh", "immagine": "/Cambogia3.jpg", "testo": "<b>Mattina:</b> Trasferimento a Phnom Penh<br><br><b>Pomeriggio:</b> Shopping nei mercati come il Central Market<br><br><b>Sera:</b> Cena d''addio"},
  {"titolo": "Day 12: Rientro in Italia", "immagine": "/Cambogia.jpg", "testo": "<b>Mattina:</b> Trasferimento in aereoporto"}
]'::jsonb,
foto_header = '/AngkorWat.jpg',
galleria_foto = ARRAY['/Cambogia.jpg', '/Cambogia2.jpg', '/Cambogia3.jpg']
WHERE id = 30;

-- ============ ID 31: FILIPPINE ============
UPDATE viaggi SET 
descrizione = '7.641: questo è il numero delle isole che compongono l''arcipelago delle Filippine: nel nostro viaggio andremo alla scoperta di più di 15 isole, dalle dimensioni e caratteristiche geologiche più disparate. Dalla caotica Manila, ci sposteremo a Bohol, regno dei tarsi, dove faremo un primo tuffo nelle acque cristalline per poi scoprire la meraviglia delle Chocolate Hills. A Palawan, la perla tropicale delle Filippine, resteremo abbagliati dall''infinita bellezza della natura, tra fiumi sotterranei, lunghe spiagge di sabbia finissima, e gite in barca alla scoperta di baie e isolette dalla vegetazione rigogliosa. Il comun denominatore, l''inconfondibile colore turchese del Mare delle Filippine!',
itinerario = '[
  {"titolo": "Day 1-2: Partenza dall''italia", "immagine": "/Manila.jpg", "testo": "<b>Day 1:</b> Partenza dai principali aereoporti italiani<br><br><b>Day 2:</b> Arrivo a Manila e relax in hotel"},
  {"titolo": "Day 3: Alla scoperta della capitale - Manila", "immagine": "/Manila2.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Alla scoperta della bellissima e caotica capitale<br><br><b>Sera:</b> Cena e serata nella movida di Manila"},
  {"titolo": "Day 4-5: Partenza per Bohol", "immagine": "/Bohol.jpg", "testo": "<b>Day 4:</b> Sveglia presto e trasferimento all''aeroporto di Manila per il volo con destinazione Bohol. Arrivo sull''isola e trasferimento in hotel. Prima giornata di mare! Ci rilasseremo infatti sulle spiagge da cartolina dell''isola di Panglao, collegata a Bohol da un ponte, e famosa per i suoi fondali ricchi di corallo e fauna tropicale.<br><br><b>Day 5:</b> Sveglia presto e breve trasferimento verso l''interno dell''isola per ammirare lo spettacolo del viewpoint delle Chocolate Hills prima dell''arrivo dei bus turistici. Trasferimento presso il centro di conservazione dei tarsi, i primati più piccoli al mondo, famosi per i loro occhi giganti"},
  {"titolo": "Day 6-7: Verso Puerto Princesa", "immagine": "/PuertoPrincesa.jpg", "testo": "<b>Day 6:</b> Trasferimento al porto di Bohol, imbarco sul traghetto veloce per l''isola di Cebu. Volo da Cebu a Puerto Princesa, il capoluogo dell''isola di Palawan. Arrivo, trasferimento e check-in in hotel<br><br><b>Day 7:</b> Giornata dedicata all''esplorazione del Puerto Princesa Underground River. Situato a circa 50km a nord del capoluogo, si tratta del fiume sotterraneo col tratto navigabile più lungo del mondo, ed è patrimonio dell''umanità UNESCO. Partenza alle 7 da Puerto Princesa, esplorazione in barca del fiume sotterraneo, immerso in uno scenario lussureggiante, dominato da alte rocce e folta vegetazione all''esterno, e da grandi stalattiti e altre particolari formazioni rocciose all''interno"},
  {"titolo": "Day 8-9-10: Destinazione paradiso - El Nido", "immagine": "/ElNido.jpg", "testo": "<b>Day 8:</b> Partenza in mattinata da Puerto Princesa in direzione di El Nido, vero e proprio paradiso incontaminato situato nel nord di Palawan. Check-in in hotel e free time<br><br><b>Day 9-10:</b> Free time nelle spiagge adiacenti il villaggio di El Nido. Tra le più belle, merita sicuramente una citazione quella di Nacpan, che occupa una lunghissima baia semicircolare di sabbia bianca. Rientro a El Nido in serata"},
  {"titolo": "Day 11-12-13: Coron", "immagine": "/Coron.jpg", "testo": "<b>Day 11:</b> Partenza in mattinata da El Nido in direzione Coron.<br><br><b>Day 12-13:</b> In relazione all''orario di arrivo possibilità di snorkeling al reef di Siete Pecados o trekking sul monte Tapyas per una splendida vista al tramonto della baia di Coron. Relax tra il mare cristallino ed i servizi offerti dell''hotel"},
  {"titolo": "Day 14-15-16: Lago Kayangan e Twin Lagoon", "immagine": "/TwinLagoon.jpg", "testo": "<b>Day 14:</b> Partenza in mattinata da Coron in direzione Lago Kayangan.<br><br><b>Day 15-16:</b> Ultima, spettacolare giornata di mare alle Filippine. La destinazione odierna è l''isola di Coron vera e propria, a circa un''ora di barca da Coron City: il lago di Kayangan è uno spettacolo che non riusciremo a dimenticare facilmente, e da lì ci sposteremo nelle meravigliose spiagge e lagune dei dintorni, come Smith Beach, il vicino coral reef perfetto per lo snorkeling, la Twin Lagoon e il Barracuda Lake. Rientro a Coron nel tardo pomeriggio, relax e free time"},
  {"titolo": "Day 17: Ritorno a Manila prima del rientro verso casa", "immagine": "/Manila.jpg", "testo": "<b>Day 17:</b> Partenza in mattinata in direzione Manila. Ultima cena e serata a Manila."},
  {"titolo": "Day 18: Rientro in Italia", "immagine": "/Manila2.jpg", "testo": "<b>Day 18:</b> Si torna a casa, alla prossima avventura insieme!"}
]'::jsonb,
foto_header = '/ElNido.jpg',
galleria_foto = ARRAY['/ElNido.jpg', '/Manila.jpg', '/TwinLagoon.jpg']
WHERE id = 31;

-- ============ ID 32: PALMA DI MALLORCA ============
UPDATE viaggi SET 
descrizione = 'Dimenticate i luoghi comuni: questo viaggio di 10 giorni vi svelerà l''essenza più autentica e raffinata di Maiorca, la regina delle Isole Baleari. L''itinerario parte dalla vibrante Palma, con la sua maestosa cattedrale gotica affacciata sul mare e i vicoli ricchi di storia, per poi spingersi verso paesaggi inaspettati. Attraverseremo la catena montuosa della Sierra de Tramuntana (Patrimonio UNESCO), punteggiata da borghi di pietra amati da artisti e poeti, navigheremo verso scogliere vertiginose a Cap de Formentor e ci tufferemo in calas (calette) nascoste, dove il profumo dei pini marittimi si fonde con acque di un turchese abbagliante. Un equilibrio perfetto tra cultura, natura selvaggia, relax caraibico ed eccellente gastronomia mediterranea.',
itinerario = '[
  {"titolo": "Day 1: Partenza dall''italia", "immagine": "/Palma.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dai principali aereoporti italiani. Arrivo a Palma de Mallorca e check-in in hotel<br><br><b>Sera:</b> Cena e relax in hotel"},
  {"titolo": "Day 2: I Capolavori di Palma e il Castello Circolare", "immagine": "/Palma2.jpg", "testo": "<b>Mattina:</b> Visita guidata dell''imponente Cattedrale (La Seu) e dell''adiacente Palazzo Reale dell''Almudaina.<br><br><b>Pomeriggio:</b> Spostamento al Castello di Bellver, unico per la sua pianta circolare, per godere di una vista panoramica mozzafiato sulla baia di Palma.<br><br><b>Sera:</b> Esplorate il quartiere bohémien di Santa Catalina, cuore della movida gastronomica. Cena in una tipica marisquería per gustare pesce fresco."},
  {"titolo": "Day 3: L''Incanto della Sierra de Tramuntana - Valldemossa e Deià", "immagine": "/Palma3.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Ritiro dell''auto e partenza verso la Sierra de Tramuntana. Sosta a Valldemossa, borgo di vicoli acciottolati celebre per la Real Cartuja. Proseguimento verso Deià.<br><br><b>Sera:</b> Cena romantica in una finca (tenuta rurale) nei dintorni, assaporando il tipico maialino da latte arrosto (porcella)."},
  {"titolo": "Day 4-5: Viaggio nel Tempo, il Nord Selvaggio e Cap de Formentor", "immagine": "/Palma4.jpg", "testo": "<b>Day 4:</b> Arrivo a Sóller e spostamento in tram aperto fino al porto. Pomeriggio di relax sulla spiaggia a ferro di cavallo.<br><br><b>Day 5:</b> Guida panoramica verso le falesie di Cap de Formentor. Sosta al Faro e tuffo rinfrescante nella favolosa Playa de Formentor."},
  {"titolo": "Day 6-7: Grotte Misteriose, Calette Nascoste e «Caraibi» a Es Trenc", "immagine": "/Palma5.jpg", "testo": "<b>Day 6:</b> Scoperta delle calette della costa est: tuffi nell''acqua cristallina di Cala Romàntica o della selvaggia Cala Varques.<br><br><b>Day 7:</b> Relax assoluto sulla spiaggia di Es Trenc: scenari caraibici, sabbia fine, mare turchese e dune incontaminate."},
  {"titolo": "Day 8-9: L''Isola Disabitata di Cabrera e i Sapori dell''Entroterra", "immagine": "/Palma6.jpg", "testo": "<b>Day 8:</b> Sbarco, bagno mozzafiato alla Cueva Azul (Grotta Azzurra) e passeggiata fino al castello panoramico dell''isola.<br><br><b>Day 9:</b> Ultimo pomeriggio di sole in una cala o tempo per lo shopping (ceramiche o perle) nel centro di Palma."},
  {"titolo": "Day 10: Hasta Luego, Maiorca!", "immagine": "/Palma7.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo di rientro"}
]'::jsonb,
foto_header = '/Palma.jpg',
galleria_foto = ARRAY['/Palma.jpg', '/Palma2.jpg', '/Palma4.jpg']
WHERE id = 32;

-- ============ ID 33: INDIA ============
UPDATE viaggi SET 
descrizione = 'L''India è un universo a sé: una terra di colori intensi, profumi inebrianti, spiritualità millenaria e contrasti forti che lasciano un''impronta indelebile in chi la visita. In questo viaggio esploreremo il celebre «Triangolo d''Oro» e oltre: dalla caotica Delhi alla blu Jodhpur, dal tempio giainista di Ranakpur alla romantica Udaipur, città dei laghi, fino alla rosa Jaipur e al mistico Taj Mahal di Agra. Un viaggio tra palazzi maharaja, mercati di spezie, templi sacri e l''incredibile umanità che popola questo Paese unico al mondo.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Delhi", "immagine": "/Delhi.jpg", "testo": "<b>Pomeriggio:</b> Arrivo in hotel, check-in e riposo"},
  {"titolo": "Day 2-3: Visita di Delhi", "immagine": "/Delhi2.jpg", "testo": "<b>Day 2:</b> Compatibilmente con l''operativo voli arrivo in nottata a Delhi, disbrigo delle pratiche d''ingresso nel paese e trasferimento in città. Check-in e ultime ore della notte in hotel. Con i suoi quasi trenta milioni di abitanti questa enigmatica città del nord, è la più popolosa dell''India e tra le più popolose al mondo. Colazione in hotel e intera giornata dedicata all''esplorazione della caotica ed affascinante parte vecchia di Delhi, quella che tra le metà del Diciassettesimo e del Diciannovesimo secolo è stata la capitale del potente Impero Moghul. Visita in mattinata del maestoso Forte Rosso<br><br><b>Day 3 mattina/pomeriggio:</b> Immersione completa nel frenetico andirivieni della moltitudine di persone che affollano il mercato tradizionale di Chandni Chowk e successiva visita della Jama Masjid, la moschea più importante di Delhi e più grande dell''India<br><br><b>Day 3 sera:</b> Partenza del treno notturno per Jodhpur. Notte in treno"},
  {"titolo": "Day 4-5-6: Jodhpur ed il tempio di Giainistra di Ranakpur", "immagine": "/Jodhpur.jpg", "testo": "<b>Day 4:</b> Arrivo alla stazione di Jodhpur, seconda città per popolazione dello stato nord-occidentale del Rajasthan. Colazione e intera giornata dedicata alla scoperta del dedalo di vicoli della coloratissima città blu dell''India, sormontata dall''imponente Forte di Mehrangarh. Cena, serata e notte in hotel a Jodhpur<br><br><b>Day 5 mattina:</b> Colazione e partenza al mattino con minivan privato in direzione Udaipur<br><br><b>Day 5 pomeriggio/sera:</b> Pranzo lungo il tragitto e sosta nel pomeriggio per ammirare il maestoso tempio di Ranakpur, appartenente all''antica religione del Giainismo, sostenuto da oltre mille colonne di marmo, scolpite nei più minimi dettagli. Arrivo nel pomeriggio a Udaipur, check-in in hotel e free-time. Cena e notte in hotel a Udaipur<br><br><b>Day 6:</b> Dopo la città blu di Jodhpur, giunge il momento di conoscere Udaipur, la città dei laghi, o la città bianca. Intera giornata alla scoperta di questo luogo fiabesco nato su due laghi, il Pichola e il Fateh Sargar. La bellezza dei suoi magnificenti palazzi nobiliari dell''Era Rajput, tra cui spicca il City Palace, e dei suoi templi hinduisti si riflette con vanità negli specchi d''acqua dei due laghi cittadini, creando immagini di austera ed esotica eleganza. Cena e serata a Udaipur."},
  {"titolo": "Day 7-8-9: verso Jaipur e l''Amber Fort di Jaipur", "immagine": "/Jaipur.jpg", "testo": "<b>Day 7 mattina:</b> Colazione e partenza in minivan in direzione Jaipur<br><br><b>Day 7 pomeriggio/sera:</b> Arrivo in tarda mattinata a Jaipur, la città rosa, la capitale dello stato del Rajasthan. Check-in in hotel e pranzo. Visita dell''antico osservatorio astronomico Jantar Mantar e dell''iconico Hava Mahal, chiamato Il Palazzo dei Venti. Cena e serata a Jaipur.<br><br><b>Day 8:</b> Spostamento ad Amer e visita del maestoso Amber Fort, una delle principali fortezze storiche del Rajasthan, nota per il suo complesso tentacolare di cortili e sale in stile tradizionale<br><br><b>Day 9:</b> Rientro a Jaipur, breve giro a piedi, recupero dei bagagli in hotel e trasferimento in minivan in direzione Agra."},
  {"titolo": "Day 10: Alla scoperta di una delle sette meraviglie del mondo - Taj Mahal", "immagine": "/TajMahal.jpg", "testo": "<b>Mattina:</b> Sveglia molto presto per ammirare il sorgere del sole sulle pietre incastonate nel marmo bianco del Taj Mahal. Tempo a disposizione per ammirare una delle 7 meraviglie del mondo, costruita da 20.000 uomini in 22 anni per volere dell''imperatore Shah Jahan, in memoria della sua amata moglie Mumtaz Mahal<br><br><b>Pomeriggio:</b> Visita del Forte Rosso di Agra, immensa fortezza in arenaria rossa costruita nel 16° secolo e fiorita sotto il regno di Shah Jahan. Recupero bagagli e trasferimento presso la stazione ferroviaria<br><br><b>Sera:</b> Partenza del treno notturno per Delhi e notte in treno"},
  {"titolo": "Day 11: Ritorno in Italia", "immagine": "/Dehli.jpg", "testo": "<b>Mattina:</b> Arrivo in mattinata nei principali scali italiani e… pronti, partenza e via! Alla prossima."}
]'::jsonb,
foto_header = '/TajMahal.jpg',
galleria_foto = ARRAY['/TajMahal.jpg', '/Dehli.jpg', '/Jaipur.jpg']
WHERE id = 33;

-- ============ ID 34: KENYA ============
UPDATE viaggi SET 
descrizione = 'Lungo le piste poco battute del Kenya, incontrando gruppi etnici dalle tradizioni intatte, attraversando il deserto di Chalbi fino all''abbagliante bellezza del lago Turkana e del cratere Nabuyatom. Un viaggio a ritroso nel tempo, alla scoperta di uno dei volti meno conosciuti del paese: dalle savane dei guerrieri Samburu, che costeggiano le pendici delle vette innevate del Monte Kenya, ricche di fauna selvaggia, alle carovane di dromedari dei Rendille, che attraversano le aride distese del Chalbi deserto, dalle barche scavate nei tronchi degli El Molo, che solcano le sponde del lago Turkana abitate da colonie di fenicotteri, ai ricchi ornamenti delle donne Turkana e Pokot, fino all''imponente monumento di nera roccia lavica del vulcano Nabuyatom, che si specchia nelle pozze smeraldo delle sue acque alcaline.',
itinerario = '[
  {"titolo": "Day 1-2: Partenza dall''italia", "immagine": "/Nairobi.jpg", "testo": "<b>Day 1:</b> Partenza dai principali aereoporti italiani<br><br><b>Day 2:</b> Arrivo a Nairobi, check-in e relax in hotel"},
  {"titolo": "Day 3: Nairobi - Riserva Samburu", "immagine": "/Nairobi2.jpg", "testo": "<b>Mattina:</b> Partenza verso nord, attraversando la caotica capitale del Kenya<br><br><b>Pomeriggio:</b> Lungo il tragitto ci fermeremo a Nanyuki per vedere il punto esatto dove passa la linea dell''equatore, e tempo permettendo anche delle bianche vette del Monte Kenya, con i suoi 5.199 metri, prima di proseguire verso la riserva del Samburu con arrivo per pranzo in hotel. Nel primo pomeriggio fotosafari in una delle aree protette più impressionanti del paese, sia per la quantità e diversità di fauna selvaggia, che per gli splendidi paesaggi. Oltre ai grandi felini, sempre molto schivi, e la giraffa Masai, la vera attrattiva del parco sono gli special 5, animali che si trovano solamente in questo parco: la zebra di Grevy, la giraffa reticolata, lo struzzo somalo, la gazzella-giraffa e l''orice dalle orecchie frangiate.<br><br><b>Sera:</b> Cena e pernottamento"},
  {"titolo": "Day 4-5-6-7: Marsabit / Kalacha / Loiyangalani", "immagine": "/Loiyangalani.jpg", "testo": "<b>Day 4:</b> Sveglia all''alba e fotosafari alla ricerca degli animali del parco prima del rientro per colazione. Breve visita ai pastori dell''etnia Samburu o Lokop: gruppo nilotico dedito all''allevamento di zebù, pecore, capre e dromedari, strettamente connessi ai Masai. Visita di una manyatta, gruppo di capanne circolari costruite con legno, fango e sterco di mucca, e delle vistose collane di donne, fatte di perline colorate cucite sul cuoio, ed i bracciali di rame sui polsi e le caviglie. Con un pò di fortuna, potremo anche incontrare i guerrieri Samburu. Proseguimento verso nord con pranzo a sacco<br><br><b>Day 5:</b> Arrivo al Parco di Marsabit, oasi montana all''interno di una vasta area desertica, lungo il sentiero avvistamento agli splendidi laghi incastonati nella vegetazione, nonché, con un po'' di fortuna, zebre, bufali ed elefanti. Prosecuzione verso Marsabit, ed incontro lungo la strada con le donne dell''etnia Borana, riconoscibili per i loro veli dai colori sgargianti. Cena e pernottamento in hotel<br><br><b>Day 6:</b> Partenza verso nord, lungo le aride distese del deserto di Kasiut, abitato dai semi-nomadi dell''etnia Rendille, appartenenti al ceppo cuscitico orientale, dediti principalmente all''allevamento di cammelli. Visita di un gob, accampamento costituito da gruppi di capanne circolari di forma rotondeggiante, ricoperte di stuoie e pelli, e recinti per gli animali. Attraversamento del deserto di Chalbi, dove un tempo si trovava un lago salato, fino a raggiungere l''oasi di Kalacha. Visita della Cattedrale, con i suoi dipinti in stile naif, e del punto di abbeverata dei dromedari.<br><br><b>Day 7:</b> Prosecuzione verso il Lago Turkana, il bacino permanente più grande al mondo in area desertica, nonché il più grande lago alcalino. Arrivo nel tardo pomeriggio a Loiyangalani."},
  {"titolo": "Day 8-9-10: Direzione paradiso - Watamu", "immagine": "/Watamu.jpg", "testo": "<b>Day 8:</b> Sveglia all''alba e volo interno verso Watamu, check-in e relax in hotel<br><br><b>Day 9-10:</b> Relax e mare cristallino, escursioni verso Sardegna 2 e tutte le altre spiagge paradisiache!"},
  {"titolo": "Day 11: Rientro in Italia", "immagine": "/Nairobi.jpg", "testo": "<b>Day 11:</b> Sveglia all''alba e volo verso casa. Alla prossima avventura!"}
]'::jsonb,
foto_header = '/Nairobi.jpg',
galleria_foto = ARRAY['/Watamu.jpg', '/Nairobi.jpg', '/Nairobi2.jpg']
WHERE id = 34;

-- ============ ID 35: ZANZIBAR ============
UPDATE viaggi SET 
descrizione = 'Un viaggio di 11 giorni alla scoperta di Zanzibar, l''Isola delle Spezie, dove l''Africa incontra l''Arabia in un abbraccio di culture, profumi e paesaggi mozzafiato. Dimenticate la frenesia: qui il tempo è scandito dalle maree e dal dolce ritmo swahili. Inizieremo il nostro percorso immergendoci nel fascino decadente e misterioso di Stone Town, per poi lasciarci inebriare dai profumi di antiche piantagioni. Ci sposteremo quindi verso le spiagge abbaglianti del nord, dove l''acqua è sempre balneabile, per poi scendere verso la costa est, teatro del suggestivo e magico fenomeno delle maree. Tra foreste abitate da rare scimmie rosse, atolli corallini, navigazioni su antichi velieri e grigliate di aragosta su isole deserte, vivrete l''essenza più pura dell''Oceano Indiano.',
itinerario = '[
  {"titolo": "Day 1-2: Partenza dall''italia", "immagine": "/Zanzibar.jpg", "testo": "<b>Day 1:</b> Partenza dai principali aereporti italiani<br><br><b>Day 2:</b> Arrivo a Stone Town e relax in hotel, per recuperare dal viaggio"},
  {"titolo": "Day 3: Stone Town - Il Fascino Swahili", "immagine": "/StoneTown.jpg", "testo": "<b>Mattina:</b> Trasferimento privato verso il cuore di Stone Town.<br><br><b>Pomeriggio:</b> Prima passeggiata esplorativa in autonomia tra il labirinto di vicoli, ammirando le celebri porte in legno finemente intagliate e i balconi arabeggianti.<br><br><b>Sera:</b> Tramonto sul lungomare e cena ai giardini di Forodhani: un''esperienza imperdibile dove la piazza si trasforma in un vivace mercato di street food locale a base di pesce fresco e pane chapati."},
  {"titolo": "Day 4: Storia, Spezie e Isola delle Tartarughe", "immagine": "/Zanzibar2.jpg", "testo": "<b>Mattina:</b> Visita guidata di Stone Town (Patrimonio UNESCO). Esplorerete il Mercato di Darajani, il sito dell''Antico Mercato degli Schiavi, la Cattedrale Anglicana e il Palazzo delle Meraviglie.<br><br><b>Pomeriggio:</b> Breve traversata in barca verso Changuu, nota come Prison Island. Qui potrete incontrare e dare da mangiare a una colonia di tartarughe giganti centenarie, alcune delle quali risalenti all''epoca vittoriana.<br><br><b>Sera:</b> Rientro a Stone Town. Cena in un suggestivo ristorante panoramico sui tetti della città, godendo della brezza serale e del canto del muezzin in lontananza."},
  {"titolo": "Day 5: Spice Tour e Spostamento a Nord", "immagine": "/Zanzibar3.jpg", "testo": "<b>Mattina:</b> Check-out e partenza per il famoso Spice Tour. Visita a una lussureggiante fattoria locale per scoprire, annusare e gustare le spezie allo stato naturale: chiodi di garofano, vaniglia, noce moscata, cannella e pepe.<br><br><b>Pomeriggio:</b> Trasferimento verso la costa Nord (Nungwi o Kendwa), famosa per le sue spiagge immacolate e per essere l''area meno influenzata dal fenomeno delle maree. Check-in in resort.<br><br><b>Sera:</b> Prima cena a piedi nudi sulla sabbia, accarezzati dal rumore dolce dell''Oceano Indiano."},
  {"titolo": "Day 6-7: Relax Assoluto e Vita da Spiaggia (Nungwi/Kendwa)", "immagine": "/Nungwi.jpg", "testo": "<b>Day 6-7:</b> Giornate interamente dedicate al relax assoluto sulla sabbia bianca e impalpabile come borotalco. Tuffi in acque cristalline e bagni di sole sotto le palme."},
  {"titolo": "Day 8-9: Atollo di Mnemba - Il paradiso del sud", "immagine": "/Mnemba.jpg", "testo": "<b>Day 8-9:</b> Relax totale e snorkeling leggero vicino alla riva, passeggiate lungo la costa per osservare i pescatori che riparano le reti"},
  {"titolo": "Day 10: Safari Blue a Menai Bay", "immagine": "/Menaibay.jpg", "testo": "<b>Mattina:</b> Partenza per la rinomata escursione Safari Blue. Navigazione su un tradizionale dhow a vela nella splendida Baia di Menai. Sosta su meravigliosi banchi di sabbia bianca che affiorano solo con la bassa marea.<br><br><b>Pomeriggio:</b> Snorkeling guidato in acque limpide e una spettacolare grigliata di pesce, cicale di mare e aragosta servita direttamente sull''isola di Kwale. Nel tardo pomeriggio, navigazione di ritorno accompagnata da canti locali.<br><br><b>Sera:</b> Rientro in hotel appagati e felici. Cena leggera e meritato riposo."},
  {"titolo": "Day 11: Ritorno in Italia", "immagine": "/Zanzibar.jpg", "testo": "<b>Mattina:</b> Arrivo in aereporto e rientro in Italia"}
]'::jsonb,
foto_header = '/Nungwi.jpg',
galleria_foto = ARRAY['/Zanzibar.jpg', '/Menaibay.jpg', '/Mnemba.jpg']
WHERE id = 35;

-- ============ ID 36: YEMEN ============
UPDATE viaggi SET 
descrizione = 'Chiunque abbia avuto, ormai decenni fa, il privilegio di farlo, definisce lo Yemen come uno dei viaggi più belli al mondo. Negli ultimi 20 anni, il paese è stato funestato da gravi conflitti interni, carestie e problematiche socio-economiche, rendendo i viaggi di fatto impossibili. La situazione è lontana dalla stabilità, ma c''è un raggio di luce: nella regione orientale dell''Hadramawt tra le più belle del paese, la situazione è in lento miglioramento. Ed è qui che si svolgerà la nostra spedizione, alla scoperta del porto di Mukhalla e delle remote vallate del Wadi Dawat, tra canyon e villaggi in fango arroccati su speroni rocciosi, per finire con i grattacieli ante litteram di Shibam, la mitica «Manhattan del deserto».',
itinerario = '[
  {"titolo": "Day 1-2: Partenza dall''italia", "immagine": "/Yemen.jpg", "testo": "<b>Day 1:</b> Volo dall''Italia direzione Cairo e notte lì<br><br><b>Day 2:</b> Volo dal Cairo verso Seiyun"},
  {"titolo": "Day 3: Seiyun", "immagine": "/Seiyun.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Spostamento verso Seiyun Old Town per acquisto abiti locali e visita della caotica città<br><br><b>Sera:</b> Cena in hotel e relax"},
  {"titolo": "Day 4-5: Mukalla e Wadi Sah", "immagine": "/Mukalla.jpg", "testo": "<b>Day 4:</b> Spostamento verso Wadi Sah, tra le principali città dello Yemen nonché uno dei porti più importanti del paese<br><br><b>Day 5:</b> Passeggiata tra le vie del porto, visita della fortezza della città Al-Ghawizi, e prosecuzione della visita alla città vecchia di Mukhalla e al vecchio mercato<br><br><b>Day 5 sera:</b> Cena in hotel con una bellissima vista sul Mar Arabico"},
  {"titolo": "Day 6-7-8: Wadi Doa''n e Shibam", "immagine": "/Shibam.jpg", "testo": "<b>Day 6:</b> Spostamento verso il Wadi Doa''n, una valle sbalorditiva punteggiata da antichi villaggi tradizionali. Pranzo con vista su Haid Al-Jizil, piccolo villaggio arroccato su di uno sperone di roccia nel mezzo della valle, ammirando il panorama più bello e iconico di tutto il Wadi Dawan<br><br><b>Day 7:</b> Un meraviglioso trekking fino al villaggio di Hawfah a Wadi Do''an. Spostamento verso il villaggio di Buqshan, con i suoi incredibili palazzi colorati<br><br><b>Day 8:</b> Partenza verso Ribad, visita della città della famiglia di Ben Laden e prosecuzione fino a Qarht Bahumaish, l''ultimo villaggio di Wadi Doa''n. Prosecuzione del viaggio verso Shibam con varie soste fotografiche nel percorso tra cui il villaggio di Musainah e la città di Al-Khuraiba. Pranzo con picnic sotto gli alberi di fronte alla bellezza del villaggio di Qarn Majed. Visita della città di Sif, seconda per bellezza solo a Shibam, con sosta fotografica su vari punti panoramici nella valle tra cui la città di Al-Hajjarain, ed il bellissimo tramonto con vista su Shibam."},
  {"titolo": "Day 9-10-11: Aynat e Tarim", "immagine": "/Mukalla.jpg", "testo": "<b>Day 9-10:</b> Spostamento verso Shibam. Storica capitale dell''Hadramawt, patrimonio Unesco, è definita «la Manhattan del deserto». La città è costruita interamente di fango con 500 palazzi che raggiungono l''altezza di 5-9 piani, risalenti fino al XVI secolo: si tratta quindi di veri e propri grattacieli dell''antichità, che creano uno degli skyline più incredibili al mondo. Spostamento verso Seiyun e visita delle seguenti attrazioni: old town, mercato del miele, mercato tradizionale Al-Handhal, mercato di frutta e verdura e Palazzo Al-Fals.<br><br><b>Day 11:</b> Prosecuzione verso Tarim, città storica Sufi, costruita nel fango, passeggiata tra le vie del porto, visita della fortezza della città"},
  {"titolo": "Day 12-13: Verso Seiyun e rientro a casa", "immagine": "/Yemen2.jpg", "testo": "<b>Day 12:</b> Spostamento verso Seiyun e l''ultimo giro tra le vie caotiche della città, relax in hotel<br><br><b>Day 13:</b> Volo verso il Cairo e successivamente volo verso i principali aereoporti italiani. Pronti, partenza e si parte! Alla prossima.<br><br><b>Sera:</b> Cena in hotel con una bellissima vista sul Mar Arabico"}
]'::jsonb,
foto_header = '/Yemen.jpg',
galleria_foto = ARRAY['/Yemen.jpg', '/Yemen2.jpg', '/Mukalla.jpg']
WHERE id = 36;

-- ==========================================
-- VERIFICA FINALE
-- ==========================================
SELECT id, mese, destinazione,
       LENGTH(descrizione) AS lunghezza_descrizione,
       jsonb_array_length(itinerario) AS giorni_itinerario,
       array_length(galleria_foto, 1) AS num_foto,
       foto_header
FROM viaggi 
WHERE stato = 'in_arrivo'
ORDER BY id;

-- Abbiamo aggiunto la colonna stato alle prenotazioni dei viaggi normali
-- Possibili valori: 'attiva' (default) o 'annullata'
ALTER TABLE prenotazioni_viaggi 
ADD COLUMN IF NOT EXISTS stato VARCHAR(20) DEFAULT 'attiva';

-- Tutte le prenotazioni esistenti diventano automaticamente 'attiva'
UPDATE prenotazioni_viaggi SET stato = 'attiva' WHERE stato IS NULL;

-- Stessa cosa per le prenotazioni dei viaggi misteriosi
ALTER TABLE prenotazioni_misteriose 
ADD COLUMN IF NOT EXISTS stato VARCHAR(20) DEFAULT 'attiva';

UPDATE prenotazioni_misteriose SET stato = 'attiva' WHERE stato IS NULL;

-- Verifichiamo
SELECT codice, stato FROM prenotazioni_viaggi LIMIT 5;

