-- ============================================================
-- VIAGGI IN ARRIVO (foto_header + itinerario + galleria_foto)
-- ============================================================

-- id=25  Tromso → Tromso28
UPDATE viaggi SET
  foto_header   = REPLACE(foto_header,   '/Tromso.jpg', '/Tromso28.jpg'),
  galleria_foto = ARRAY(SELECT REPLACE(f, '/Tromso.jpg', '/Tromso28.jpg') FROM unnest(galleria_foto) f),
  itinerario    = REPLACE(itinerario::text, '/Tromso.jpg', '/Tromso28.jpg')::jsonb
WHERE id = 25;

