-- ============================================================
-- VERIFICA (devono tornare 0 righe)
-- ============================================================
SELECT id, destinazione, foto_header FROM viaggi
WHERE foto_header IN (
  '/Norvegia.jpg','/Lapponia.jpg','/Londra.jpg','/Marocco.jpg',
  '/Peru.jpg','/Thailandia.jpg','/Oman.jpg','/Cartagine.jpg',
  '/Messico.jpg','/Yemen.jpg','/Nungwi.jpg','/Nairobi.jpg',
  '/TajMahal.jpg','/Tromso.jpg','/IslaSaona.jpg','/Uganda.jpg','/Palma.jpg'
);

SELECT id, destinazione FROM viaggi
WHERE itinerario::text LIKE '%/Messico.jpg%'
   OR itinerario::text LIKE '%/Yemen.jpg%'
   OR itinerario::text LIKE '%/Nungwi.jpg%'
   OR itinerario::text LIKE '%/Nairobi.jpg%'
   OR itinerario::text LIKE '%/TajMahal.jpg%'
   OR itinerario::text LIKE '%/Tromso.jpg%'
   OR itinerario::text LIKE '%/IslaSaona.jpg%'
   OR itinerario::text LIKE '%/Uganda.jpg%'
   OR itinerario::text LIKE '%/Palma.jpg%';

