  foto_header   = REPLACE(foto_header,   '/Tromso6.jpg', '/Tromso5.jpg'),
  galleria_foto = ARRAY(SELECT REPLACE(f, '/Tromso6.jpg', '/Tromso5.jpg') FROM unnest(galleria_foto) f),
  itinerario    = REPLACE(itinerario::text, '/Tromso6.jpg', '/Tromso5.jpg')::jsonb
WHERE id = 25;

-- /Tunisia.jpg → /Tunisia2.jpg  (id=4, foto_header)
UPDATE viaggi SET foto_header = '/Tunisia2.jpg'
WHERE id = 4 AND foto_header = '/Tunisia.jpg';


