-- Delhi28: aggiornala nei viaggi che la usano come seconda immagine
UPDATE viaggi SET
  itinerario    = REPLACE(itinerario::text,    '/Delhi28.jpg', '/Delhi28.jpg')::jsonb,
  galleria_foto = ARRAY(SELECT REPLACE(f, '/Delhi27.jpg', '/Delhi28.jpg') FROM unnest(galleria_foto) f)
WHERE galleria_foto::text LIKE '%Delhi%'
  AND array_length(galleria_foto, 1) > 1
  AND galleria_foto[2] LIKE '%Delhi%';

  -- Ripristina Jaipur27.jpg → Jaipur.jpg
UPDATE viaggi SET
  foto_header   = REPLACE(foto_header,   '/Jaipur27.jpg', '/Jaipur.jpg'),
  galleria_foto = ARRAY(SELECT REPLACE(f, '/Jaipur27.jpg', '/Jaipur.jpg') FROM unnest(galleria_foto) f),
  itinerario    = REPLACE(itinerario::text, '/Jaipur27.jpg', '/Jaipur.jpg')::jsonb
WHERE foto_header = '/Jaipur27.jpg'
   OR itinerario::text LIKE '%/Jaipur27.jpg%'
   OR array_to_string(galleria_foto, ',') LIKE '%/Jaipur27.jpg%';

   -- Azzera posti_totali e posti_disponibili per tutti i viaggi in_arrivo
UPDATE viaggi
SET posti_totali = 0,
    posti_disponibili = 0
WHERE stato = 'in_arrivo';
